'use strict';
/* Futtatás: node tests/run.js   (nincs külső függőség). Logikát és kivételeket ellenőriz – megjelenést, érintést, hangot nem. */
const {boot}=require('./harness');
let pass=0,fail=0;const only=process.argv[2]&&!/^\d+\/\d+$/.test(process.argv[2])?process.argv[2]:undefined;let grp='',gi=-1;const SH=(process.env.SHARD||(/^\d+\/\d+$/.test(process.argv[2]||'')?process.argv[2]:'')).split('/').map(Number);const shardOn=SH.length===2&&SH[1]>0;
const group=n=>{grp=n;gi++;console.log('\n'+n)};
function t(name,fn){if(only&&!grp.toLowerCase().includes(only.toLowerCase()))return;if(shardOn&&gi%SH[1]!==SH[0])return;try{fn();pass++;console.log('  ✓',name)}catch(e){fail++;console.log('  ✗',name,'→',e.message)}}
const eq=(a,b,m)=>{if(JSON.stringify(a)!==JSON.stringify(b))throw new Error((m||'')+' várt: '+JSON.stringify(b)+' kapott: '+JSON.stringify(a))};
const near=(a,b,e,m)=>{if(!(Math.abs(a-b)<=e))throw new Error((m||'')+' várt ≈ '+b+' kapott: '+a)};
const ok=(c,m)=>{if(!c)throw new Error(m||'feltétel hamis')};
const legacy=(x={})=>JSON.stringify(Object.assign({cash:123456,depth:0,st:'idle',fuel:250,hp:93,u:{d:1,h:1,t:1,c:1},cg:{'Kőszén':12.5},fin:{},disc:{'Római ezüstdénár':1},max:812,t:1.7e12,log:['régi'],set:{vol:30,sc:600,auto:0},won:0,x:0,tr:[],tn:[[0,0,0,812]]},x));

group('A) Mentés: betöltés, migráció, védelem');
t('régi (verziótlan) mentés változatlanul betöltődik, v=aktuális',()=>{const raw=legacy(),g=boot({store:{drillup1:raw}}),S=g.T.S;
 eq(S.cash,123456);eq(S.u,{d:1,h:1,t:1,c:1,f:0,g:0,b:0});eq(S.set.vol,30);eq(S.set.sc,600);eq(S.set.auto,0);eq(S.cg['Kőszén'],12.5);eq(S.max,812);eq(S.tn.map(a=>a.slice(0,4)),[[0,0,0,812]]);eq(S.v,g.sb.Save.VER);eq(S.set.q,'a');eq(S.gf,60);eq(S.gon,1);eq(S.en,0)});
t('migráció előtt másolat készül (drillup1_pre_v1) és nem íródik felül',()=>{const raw=legacy(),g=boot({store:{drillup1:raw}});eq(g.store.drillup1_pre_v1,raw);
 g.store.drillup1=legacy({cash:5});const g2=boot({store:g.store});eq(g2.store.drillup1_pre_v1,raw,'az első másolat marad')});
t('sérült főmentés → tartalék betöltése, a sérült megőrzése',()=>{const g=boot({store:{drillup1:'{rossz',drillup1_bak:legacy({cash:777})}});eq(g.T.S.cash,777);eq(g.store.drillup1_corrupt,'{rossz');eq(g.sb.Save.info.src,'drillup1_bak')});
t('minden sérült → tiszta kezdőállapot, nincs kivétel',()=>{const g=boot({store:{drillup1:'xx',drillup1_bak:'yy'}});eq(g.T.S.cash,250000)});
t('értékek ellenőrzése: kivett/rossz mezők javítása',()=>{const raw=legacy({u:{d:99,h:-4,t:'x',c:1.5},st:'zzz',fuel:null,depth:-5,cg:{'Nincs ilyen':5,'Kőszén':-3,'Homok':7},fin:{'x':2},tr:'rossz',tn:[[1,2]],hp:500,log:[1,'ok']});
 const g=boot({store:{drillup1:raw}}),S=g.T.S;eq(S.u.d,g.T.D.length-1);eq(S.u.h,0);eq(S.u.t,0);eq(S.u.c,0);eq(S.st,'idle');eq(S.fuel,300);eq(S.depth,0);eq(S.cg,{'Homok':7});eq(S.fin,{});eq(S.tr,[]);eq(S.tn,[]);eq(S.hp,100);eq(S.log,['ok'])});
t('mélyen lévő gép mentése visszaúttal pótlódik',()=>{const g=boot({store:{drillup1:legacy({depth:300,tr:[]})}});eq(g.T.S.tr,[['D',300]])});
t('mentés kihagyja a sérült (NaN) állapotot, a főmentés érintetlen',()=>{const g=boot();g.sb.Save.save(g.T.S);const before=g.store.drillup1;g.T.S.cash=NaN;eq(g.sb.Save.save(g.T.S),false);eq(g.store.drillup1,before)});
t('tárhely-hiba nem dob kivételt, majd felépül',()=>{const g=boot();g.st.quota=true;eq(g.sb.Save.save(g.T.S),false);ok(g.sb.Save.err);g.st.quota=false;eq(g.sb.Save.save(g.T.S),true);eq(g.sb.Save.err,null)});
t('gördülő tartalék: 10 perc után frissül, az előző a bak2-be kerül',()=>{const g=boot();g.T.S.cash=111;g.sb.Save.save(g.T.S);const b1=g.store.drillup1_bak;ok(b1);g.advance(11*60e3);g.T.S.cash=222;g.sb.Save.save(g.T.S);eq(g.store.drillup1_bak2,b1);eq(JSON.parse(g.store.drillup1_bak).cash,222)});
t('export → import oda-vissza azonos, a régi főmentés pre_import alá kerül',()=>{const g=boot();g.T.S.cash=777;g.T.S.u.d=3;const str=g.sb.Save.exportStr(g.T.S);
 const g2=boot({store:{drillup1:legacy({cash:5})}});eq(g2.sb.Save.importStr(str,g2.T.sanitizeSave,g2.T.init),null);const o=JSON.parse(g2.store.drillup1);eq(o.cash,777);eq(o.u.d,3);eq(o.v,g2.sb.Save.VER);ok(g2.store.drillup1_pre_import)});
t('érvénytelen import elutasítva, a mentés változatlan',()=>{const g=boot({store:{drillup1:legacy()}});const b=g.store.drillup1;ok(g.sb.Save.importStr('nem json',g.T.sanitizeSave,g.T.init));ok(g.sb.Save.importStr('{"a":1}',g.T.sanitizeSave,g.T.init));eq(g.store.drillup1,b)});
t('a save() esemény kisül és ment',()=>{const g=boot();let n=0;g.sb.on('save',()=>n++);g.T.save();eq(n,1);ok(g.store.drillup1)});

group('B) Eseménykampók');
t('step/sim/tick/frame/world.back/world.front/hud mind kisül, helyes adattal',()=>{const g=boot();const c={};['step','sim','tick','frame','world.back','world.front','hud','save'].forEach(e=>g.sb.on(e,a=>{c[e]=(c[e]||0)+1;c['a_'+e]=a}));
 g.engineOn();g.T.S.fuel=300;g.T.go('D');g.frames(90);g.T.tick();g.T.save();
 for(const e of['step','sim','tick','frame','world.back','world.front','hud','save'])ok(c[e]>0,e+' nem sült ki');
 ok(typeof c['a_step']==='number'&&typeof c['a_sim']==='number'&&typeof c['a_frame']==='number');const V=c['a_world.back'];ok(typeof V.SX==='function'&&typeof V.cx==='number'&&V.K===10&&typeof V.lamp==='function'&&Array.isArray(V.GL))});
t('a hibás figyelő nem állítja le a játékot, a hiba látszik a hibakeresőben',()=>{const g=boot();g.sb.on('step',()=>{throw new Error('teszt')});g.engineOn();g.T.S.fuel=300;g.T.go('R');const e=g.frames(60);ok(g.T.S.x>0,'a gép mozdult');ok(e.some(m=>/step: teszt/.test(m)),'a hiba nem látszik')});

group('C) Teljesítmény-szabályozó');
t('lassú képkockáknál lejjebb vált, utána nem pattog vissza',()=>{const g=boot(),G=g.sb.Gov;G.init('a');eq(G.q,2);for(let i=0;i<80;i++)G.frame(40);eq(G.q,1,'3,2 mp után egy fokozat');for(let i=0;i<300;i++)G.frame(40);eq(G.q,0);for(let i=0;i<300;i++)G.frame(16.7);eq(G.q,0,'60 mp-ig tilos felfelé')});
t('hosszú gyors futás után felvált',()=>{const g=boot(),G=g.sb.Gov;G.init('a');for(let i=0;i<200;i++)G.frame(40);const q0=G.q;for(let i=0;i<6000;i++)G.frame(16.7);ok(G.q>q0)});
t('kézi mód állandó, értékek: részecske 90/160/260, DPR-sapka 1/1,5/2',()=>{const g=boot(),G=g.sb.Gov;G.setMode('0');eq([G.parts(),G.dpr(3),G.dust()],[90,1,false]);for(let i=0;i<500;i++)G.frame(60);eq(G.q,0);G.setMode('1');eq([G.parts(),G.dpr(3)],[160,1.5]);G.setMode('2');eq([G.parts(),G.dpr(3),G.dpr(1)],[260,2,1])});
t('a beállítás a mentésbe kerül és visszatölt',()=>{const g=boot();g.T.S.set.q='1';g.sb.Gov.setMode('1');g.T.save();const g2=boot({store:g.store});eq(g2.T.S.set.q,'1');eq(g2.sb.Gov.q,1)});
t('alacsony minőségnél kevesebb részecske keletkezik',()=>{const run=q=>{const g=boot();g.engineOn();g.sb.Gov.setMode(String(q));const S=g.T.S;S.depth=50;S.tr=[['D',50]];S.tn=[[0,0,0,50]];S.fuel=500;g.T.go('D');g.frames(240);return g.T.pr.length};ok(run(0)<run(2),'Q0 < Q2')});

group('D) Regresszió: a meglévő játék működik');
t('koppintás: elindul és tart; újabb koppintás megállít',()=>{const g=boot(),T=g.T;g.engineOn();T.S.set.sc=60;T.S.set.arc=0;T.pd('D',g.ev);T.pu();g.frames(120);eq(T.S.st,'D');ok(T.S.depth>0.3,'mélyült');T.pd('D',g.ev);T.pu();g.frames(5);eq(T.S.st,'idle')});
t('nyomva tartás: amíg tartod megy, felengedésre megáll',()=>{const g=boot(),T=g.T;g.engineOn();T.S.set.sc=60;T.pd('R',g.ev);g.runTimers();g.frames(60);eq(T.S.st,'R');ok(T.hold&&T.hold.mom);T.pu();g.frames(3);eq(T.S.st,'idle')});
t('irányváltás új nyomással',()=>{const g=boot(),T=g.T;T.pd('L',g.ev);T.pu();g.frames(30);T.pd('R',g.ev);eq(T.S.st,'R');T.pu()});
t('kevés üzemanyag: automatikus tankolás indulás előtt',()=>{const g=boot(),T=g.T;g.engineOn();T.S.fuel=3;g.T.go('D');g.frames(60);eq(T.S.st,'D');ok(T.S.fuel>100);ok(T.S.cash<250000)});
t('nincs pénz: nem indul, érthető üzenet',()=>{const g=boot(),T=g.T;T.S.fuel=3;T.S.cash=0;T.go('D');eq(T.S.st,'idle');ok(g.toasts.some(m=>/Kevés az üzemanyag/.test(m)))});
t('kemény kőzet: gránit előtt megáll 0-s fejjel, 1-es fejjel halad',()=>{const g=boot(),T=g.T,S=T.S;g.engineOn();S.depth=3999.995;S.tr=[['D',3999.995]];S.fuel=800;S.set.auto=0;S.set.sc=1;T.go('D');g.frames(300);eq(S.st,'idle');ok(S.depth>3999.99&&S.depth<4000.001);S.u.f=1;T.go('D');g.frames(200);eq(S.st,'D');ok(S.depth>4000)});
t('vészüzemanyag: üres tartálynál a raktárból éget',()=>{const g=boot(),T=g.T,S=T.S;g.engineOn();S.depth=10;S.tr=[['D',10]];S.fuel=0;S.cg={'Kőszén':50};T.go('D');g.frames(30);ok(S.fuel>0);ok(S.cg['Kőszén']<50);eq(S.st,'D')});
t('gyors hazatérés 6 mp alatt hazaér',()=>{const g=boot(),T=g.T,S=T.S;g.engineOn();S.depth=1200;S.x=300;S.tr=[['R',300],['D',1200]];S.fuel=800;S.cg={};T.go('H');let f=0;for(;f<600&&S.st=='H';f++)g.frames(1);ok(f*16.7<6000,'túl lassú: '+f);eq(S.depth,0);eq(S.x,0)});
t('mélyen kifogyó üzemanyag: a gép elvész, a pénz megmarad',()=>{const g=boot(),T=g.T,S=T.S;g.engineOn();S.depth=100;S.tr=[['D',100]];S.fuel=0.0001;S.cg={};S.set.auto=0;S.cash=4242;T.go('U');g.frames(400);ok(S.depth==0||S.st=='idle');eq(S.cash,4242)});
t('rajzolás: minden meghajtás/páncél/fúrófej-szinten kivétel nélkül',()=>{const g=boot(),T=g.T,S=T.S;let errs=[];for(let k=0;k<7;k++){S.u.d=k;S.u.h=Math.min(5,k);S.u.f=Math.min(5,k);errs=errs.concat(g.frames(6))}eq(errs,[])});
t('rajzolás: mélyen, alagúttal, lefelé és vízszintesen fúrva',()=>{const g=boot(),T=g.T,S=T.S;S.depth=500;S.tn=[[0,0,0,500],[0,500,80,500]];S.x=40;S.tr=[['D',500],['R',40]];S.fuel=500;S.set.sc=60;let e=[];for(const d of['R','L','D','U']){T.go(d);e=e.concat(g.frames(90))}eq(e,[])});
t('főmenü és hős-jelenet: 200 képkocka, kivétel nélkül; a menü alatt a játékrajz szünetel',()=>{const g=boot({menu:true}),T=g.T;let bad=0;for(let i=0;i<200;i++){g.advance(17);try{T.hero(g.mc,i*17)}catch(e){bad++}}eq(bad,0);T.showMM();T.showMM('set');eq(g.frames(10),[])});
t('panelek (adatok/raktár/fúrófej) szövege felépül',()=>{const g=boot();for(const k of['info','store','head']){g.T.sheetT=k;const h=g.T.sheetHTML();ok(typeof h==='string'&&h.length>40,k)}});
t('base.js nélkül is elindul és játszható (tartalék ágak)',()=>{const g=boot({skip:['js/base.js']});ok(!g.sb.Save&&!g.sb.Gov);g.engineOn();g.T.S.fuel=300;g.T.go('R');eq(g.frames(60),[]);ok(g.T.S.x>0);g.T.save();ok(g.store.drillup1)});


group('E) 1. fázis: motor, áramfejlesztő, blueprint');
const base0=(o={})=>{const g=boot(o);g.T.S.set.sc=1;return g};
t('motor: kikapcsolva nem mozdul; az irány gomb automatikusan beindítja, ~2-4 mp után halad',()=>{const g=base0(),T=g.T,S=T.S;eq(S.en,0);S.fuel=300;T.go('R');g.frames(30);eq(S.x,0,'0,5 mp-nél még áll');eq(S.en,1);let f=30;for(;f<400&&!g.sb.ENG.ready();f++)g.frames(1);ok(f>90&&f<300,'felpörgés ideje: '+(f*16.7/1000).toFixed(1)+' mp');g.frames(120);ok(S.x>1,'halad')});
t('motor: kézi kapcsoló be/ki, kikapcsoláskor megáll a gép',()=>{const g=base0(),T=g.T,S=T.S;g.sb.PW.toggleEng();eq(S.en,1);g.frames(250);ok(g.sb.ENG.ready());T.go('R');g.frames(30);g.sb.PW.toggleEng();eq(S.en,0);eq(S.st,'idle');g.frames(150);eq(g.sb.ENG.rpm,0)});
t('motor: üresjáratban fogyaszt, 120 mp után magától leáll',()=>{const g=base0(),T=g.T,S=T.S;g.engineOn();S.fuel=300;g.sb.ENG.ld=.08;g.advance(130e3);T.sim();eq(S.en,0);const burn=300-S.fuel;ok(burn>.5&&burn<1.2,'üresjárati fogyasztás: '+burn.toFixed(2)+' kg');ok(S.log.some(m=>/üresjárati/.test(m)))});
t('motor: nincs üzemanyag → nem indul, érthető üzenet',()=>{const g=base0(),T=g.T,S=T.S;S.fuel=0;eq(g.sb.PW.toggleEng(),undefined);eq(S.en,0);ok(g.toasts.some(m=>/Nincs üzemanyag/.test(m)))});
t('terhelés: a kemény kőzet terhelőbb mint a talaj',()=>{const ld=d=>{const g=base0(),T=g.T,S=T.S;g.engineOn();S.fuel=800;S.depth=d;S.tr=[['D',d]];T.go('D');g.frames(200);return g.sb.ENG.ld};const a=ld(10),b=ld(1000);ok(b>a+.15,'talaj '+a.toFixed(2)+' / kőzet '+b.toFixed(2))});
t('fogyasztás: puha kőzetben kevesebb üzemanyag megy el másodpercenként',()=>{const burn=d=>{const g=base0(),T=g.T,S=T.S;g.engineOn();S.fuel=800;S.depth=d;S.tr=[['D',d]];T.go('D');g.frames(60);const f0=S.fuel;g.frames(300);return(f0-S.fuel)/(300*.0167)};const a=burn(10),b=burn(1000);ok(a<b*.9,'talaj '+a.toFixed(3)+' < kőzet '+b.toFixed(3)+' kg/s')});
t('generátor: fogyasztás időarányos (30 kW, 25 kW igény → ~37,5 kg/óra)',()=>{const g=base0(),T=g.T,S=T.S;S.gon=1;S.gf=60;g.sb.GEN.step(3600);ok(Math.abs(60-S.gf-37.5)<1.5,'fogyott: '+(60-S.gf).toFixed(1))});
t('generátor: be/ki kapcsoló, üres tankkal nem kapcsol be',()=>{const g=base0(),T=g.T,S=T.S;S.gon=0;S.gf=0;g.sb.GEN.toggle();eq(S.gon,0);ok(g.toasts.some(m=>/Üres a generátor/.test(m)));S.gf=10;g.sb.GEN.toggle();eq(S.gon,1);g.sb.GEN.toggle();eq(S.gon,0)});
t('generátor: bekapcsolva ~7% gyorsabb fúrás (tehermentesíti a motort)',()=>{const g=base0(),T=g.T,S=T.S;S.depth=1000;S.gf=60;S.gon=0;const a=T.calc().v;S.gon=1;const b=T.calc().v;ok(b/a>1.05&&b/a<1.09,'arány '+(b/a).toFixed(3))});
t('generátor: elfogyó üzemanyag leállítja',()=>{const g=base0(),T=g.T,S=T.S;S.gon=1;S.gf=.0005;g.sb.GEN.step(100);eq(S.gon,0);eq(S.gf,0);ok(S.log.some(m=>/generátor üzemanyaga elfogyott/.test(m)))});
t('generátor: fúrás közben fogy a tank (esemény-kampó)',()=>{const g=base0(),T=g.T,S=T.S;g.engineOn();S.fuel=800;S.gon=1;S.gf=60;S.set.sc=60;T.go('D');g.frames(200);ok(S.gf<60,'a tank nem fogyott')});
t('generátor: fejlesztés (üzemanyagtípus-váltás visszatérít, tankot ürít)',()=>{const g=base0(),T=g.T,S=T.S;S.cash=1e7;S.gf=100;const c0=S.cash;T.buy('g');eq(S.u.g,1);eq(S.gf,0);eq(S.gon,0);eq(Math.round(S.cash),Math.round(c0-2.5e5+100*40*.8))});
t('gép elvesztésekor a felszíni generátor szintje megmarad, a motor leáll',()=>{const g=base0(),T=g.T,S=T.S;S.u.g=2;S.u.d=3;S.en=1;S.depth=100;T.strand('teszt');eq(S.u.g,2);eq(S.u.d,0);eq(S.en,0);eq(S.depth,0)});
t('mentés-migráció: 2-es mentés → generátor- és motor-mezők, hibás szint levágva',()=>{const g=boot({store:{drillup1:legacy({v:2,u:{d:1,h:1,t:1,c:1,f:0}})}});eq([g.T.S.u.g,g.T.S.gf,g.T.S.gon,g.T.S.en],[0,60,1,0]);eq(g.T.S.v,g.sb.Save.VER);const g2=boot({store:{drillup1:legacy({v:2,u:{d:1,h:1,t:1,c:1,f:0,g:99},gf:9999,gon:1})}});eq(g2.T.S.u.g,4);ok(g2.T.S.gf<=8.0001)});
t('világítás: a generátor ellátottsága (0 ha ki/üres, <1 ha túlterhelt)',()=>{const g=base0(),T=g.T,S=T.S,G=g.sb.GEN;S.gon=0;eq(G.sat(),0);S.gon=1;S.gf=10;ok(G.sat()>0);S.depth=1000;S.mode='drill';ok(G.sat()<1,'a Gőzdinamó 30 kW-ja kevés a mély fúráshoz');S.u.g=2;ok(G.sat()===1)});
t('kezelőfelület: dock-kapcsolók, adatpanel',()=>{const g=base0(),T=g.T;T.go('idle');ok(/id="swM"/.test(g.sb.PW.dock())&&/id="swG"/.test(g.sb.PW.dock()));T.sheetT='info';const h=T.sheetHTML();ok(/Motor/.test(h)&&/Generátor/.test(h));g.sb.PW.live()});
t('indítási animáció + generátor-rajz: kivétel nélkül minden szinten és állapotban',()=>{const g=base0(),T=g.T,S=T.S;let e=[];S.fuel=500;T.go('D');e=e.concat(g.frames(260));for(let lv=0;lv<5;lv++){S.u.g=lv;for(const on of[0,1]){S.gon=on;S.gf=on?5:0;e=e.concat(g.frames(8))}}eq(e,[])});
t('blueprint: rajz, kiválasztás, százalék, fejlesztés a bázison',()=>{const g=base0(),T=g.T,S=T.S,B=g.sb.BP;S.cash=1e10;let h=B.html();ok(/<svg/.test(h)&&/Fejlesztés –/.test(h));for(const p of B.parts){B.sel=p.k;const html=B.html();ok(html.includes(p.n),p.k);const pc=B.pct(p);ok(pc>=0&&pc<=100)}
 B.pick('f');eq(B.sel,'f');const c0=S.cash,f0=S.u.f,price=T.HD[f0+1].at(-1);B.buy();eq(S.u.f,f0+1);eq(S.cash,c0-price)});
t('blueprint: a bázison kívül nem fejleszthető, a gomb letiltva és indoklással',()=>{const g=base0(),T=g.T,S=T.S,B=g.sb.BP;S.depth=50;B.sel='h';const h=B.html();ok(/Fejleszteni csak a bázison/.test(h)&&/disabled/.test(h));const c0=S.cash;B.buy();eq(S.cash,c0)});
t('blueprint: maximális szinten nincs vásárlás, 100%',()=>{const g=base0(),T=g.T,S=T.S,B=g.sb.BP;S.u.h=T.H.length-1;B.sel='h';const h=B.html();ok(/Maximális szint/.test(h));eq(B.pct(B.parts.find(p=>p.k==='h')),100)});

group('F) 2. fázis: járathálózat, szabadesés, fék, lámpák');
const shaft=(tn,o={})=>{const g=boot();g.engineOn();const T=g.T,S=T.S;S.tn=tn;S.fuel=800;S.set.sc=o.sc||1;S.set.abk=o.abk===undefined?1:o.abk;S.depth=o.d||0;S.x=o.x||0;S.tr=o.tr||(S.depth>0?[['D',S.depth]]:[]);S.cg={};return g};
const until=(g,cond,max=3000)=>{let n=0;const E=[];for(;n<max&&!cond();n++){E.push(...g.frames(1))}return{n,errs:E}};
t('szabad tér: kapszula-vizsgálat (4,4 m széles járat, a végén nincs túlnyúlás)',()=>{const g=shaft([[0,0,0,100],[0,100,50,100]]),N=g.sb.NET;
 ok(N.free(0,50)&&N.free(2.2,50)&&!N.free(2.3,50));ok(N.free(10,100)&&N.free(10,102.2)&&!N.free(10,102.3));ok(!N.free(10,50));ok(!N.free(0,100.01+2.3));
 ok(N.free(0,100.01),'a függőleges akna alja a vízszintes járatba csatlakozik')});
t('padló és távolság: láncolt járatokon át (akna + vízszintes járat)',()=>{const g=shaft([[0,0,0,100],[0,100,50,100]]),N=g.sb.NET;ok(Math.abs(N.floor(0,50)-102.2)<1e-6,'padló '+N.floor(0,50));ok(Math.abs(N.reach(0,100,1,0)-50)<1e-6);ok(Math.abs(N.ahead(0,100,1,0)-50)<1e-6);eq(N.ahead(50,100,1,0),0)});
t('szabadesés asszisztenssel: puhán ér le, nincs sérülés, a visszaút-verem frissül',()=>{const g=shaft([[0,0,0,300]]),T=g.T,S=T.S,N=g.sb.NET;S.st='D';let vmax=0,started=false;const r=until(g,()=>{vmax=Math.max(vmax,N.vz);if(N.falling)started=true;return started&&!N.falling},2500);
 eq(r.errs,[]);ok(vmax>25,'max sebesség '+vmax.toFixed(1));ok(Math.abs(S.depth-300)<.01,'mélység '+S.depth);eq(S.hp,100);eq(S.tr,[['D',300]]);ok(S.log.some(m=>/Landolás/.test(m)))});
t('szabadesés közben nem fogy az üzemanyag, és a játékidő nem gyorsul (×60-nál is valós idejű)',()=>{const g=shaft([[0,0,0,150]],{sc:60,abk:1}),T=g.T,S=T.S,N=g.sb.NET;const f0=S.fuel;S.st='D';let started=false;const r=until(g,()=>{if(N.falling)started=true;return started&&!N.falling},1500);ok(r.n>300&&r.n<900,'esés ideje '+(r.n*16.7/1000).toFixed(1)+' mp');ok(Math.abs(S.fuel-f0)<.5,'üzemanyag')});
t('becsapódás fék nélkül: a váz sérül (5 m-es esés ≈ 30-40%)',()=>{const g=shaft([[0,0,0,5]],{abk:0}),T=g.T,S=T.S,N=g.sb.NET;S.st='D';until(g,()=>S.depth>1&&!N.falling,600);ok(S.hp<75&&S.hp>55,'hp '+S.hp.toFixed(1));ok(S.log.some(m=>/Becsapódás/.test(m)))});
t('végzetes zuhanás: a gép felrobban, TELJES újrakezdés (pénz, járatok, fejlesztések elvesznek), sírkő marad',()=>{const g=shaft([[0,0,0,300]],{abk:0}),T=g.T,S=T.S,N=g.sb.NET,D=g.sb.DMG;S.cash=4321;S.u.d=2;S.max=250;S.st='D';until(g,()=>D.busy()||(g.T.S.tb&&g.T.S.tb.length),1500);ok(D.busy()||g.T.S.tb.length>0);g.frames(400,30);const Z=g.T.S;eq(Z.u.d,0);eq(Z.depth,0);eq(Z.cash,25e4);eq(Z.tn.length,0);eq(Z.tb.length,1);eq(N.falling,false)});
t('kézi fék: lassít, de nem állítja meg – a gép tovább zuhan az aknaaljáig, sérülés nélkül (asszisztens nélkül)',()=>{const g=shaft([[0,0,0,60]],{abk:0}),T=g.T,S=T.S,N=g.sb.NET,B=g.sb.BK;S.st='D';g.frames(120);ok(N.falling&&N.vz>15);const v0=N.vz;B.down();let bkmax=0,vmin=1e9,hang=0;const r=until(g,()=>{bkmax=Math.max(bkmax,N.bk);if(N.falling&&N.bk>.5){vmin=Math.min(vmin,N.vz);if(N.vz<.5)hang++}return !N.falling},2500);eq(r.errs,[]);ok(!N.falling,'leért');ok(Math.abs(S.depth-60)<.01,'az aknaaljáig zuhant: '+S.depth.toFixed(1));ok(bkmax>.9,'a fék teljes nyomásra kapcsolt: '+bkmax.toFixed(2));ok(vmin<v0*.5,'lassított: '+vmin.toFixed(1)+' < '+v0.toFixed(1));ok(vmin>=1.5,'nem állt meg a levegőben: '+vmin.toFixed(2));eq(hang,0);eq(S.hp,100);ok(!S.log.some(m=>/rögzítőfék/.test(m)));B.up();eq(N.bkIn,0)});
t('fék: a pu() (felengedés) elengedi',()=>{const g=boot(),B=g.sb.BK;B.down();eq(g.sb.NET.bkIn,1);g.T.pu();eq(B.held,false);eq(g.sb.NET.bkIn,0)});
t('motorral mászás az aknában nem esés; üresjáratban az akna közepén sem esik le',()=>{const g=shaft([[0,0,0,100]],{d:100}),T=g.T,S=T.S,N=g.sb.NET;T.go('U');g.frames(400);ok(S.depth<99,'mászik: '+S.depth.toFixed(1));eq(N.falling,false);S.st='idle';const d=S.depth;g.frames(180);eq(N.falling,false);ok(Math.abs(S.depth-d)<1e-6)});
t('áttörés: lefelé fúrva a meglévő vízszintes járatba beleesik, a padlón áll, majd a középvonalra áll fel',()=>{const g=shaft([[0,0,0,17.6],[-20,20,20,20]],{d:17.6,sc:60}),T=g.T,S=T.S,N=g.sb.NET;S.st='D';const r=until(g,()=>S.depth>22&&!N.falling,2000);eq(r.errs,[]);ok(Math.abs(S.depth-22.2)<.05,'padló '+S.depth);
 const cg0=T.cargoKg(),n0=S.tn.length;S.set.sc=1;if(g.sb.DMG&&g.sb.DMG.st)g.sb.DMG.st().t=0;/* a ≥6%-os becsapódás véletlenül leejtheti a láncot – ez a teszt a haladást nézi */T.go('R');g.frames(150);eq(S.tn.length,n0,'nem fúr újra');ok(Math.abs(S.depth-20)<.06,'középvonal '+S.depth);ok(S.x>5,'halad: '+S.x.toFixed(1));ok(Math.abs(T.cargoKg()-cg0)<1e-9,'nincs hozam a kész járatban')});
t('meglévő vízszintes járatban nem fúr újra: nincs új szakasz, nincs hozam, kevés üzemanyag',()=>{const g=shaft([[0,50,100,50]],{d:50,x:0,tr:[['R',0.001]]}),T=g.T,S=T.S;const f0=S.fuel;T.go('R');g.frames(600);ok(S.x>40,'x '+S.x.toFixed(1));eq(S.tn.length,1);eq(T.cargoKg(),0);ok(f0-S.fuel<5,'fogyasztás '+(f0-S.fuel).toFixed(2))});
t('esés után a hazatérés a verem mentén működik',()=>{const g=shaft([[0,0,0,300]]),T=g.T,S=T.S,N=g.sb.NET;S.st='D';until(g,()=>S.depth>299&&!N.falling,2500);S.st='idle';T.go('H');let f=0;for(;f<900&&S.st=='H';f++)g.frames(1);ok(f*16.7<8000,'hazaút '+(f*16.7/1000).toFixed(1)+' mp');eq(S.depth,0)});
t('lámpák: 8 m-enként kerülnek ki az új járatba, pénzbe kerülnek',()=>{const g=boot(),T=g.T,S=T.S,L=g.sb.LMP;S.cash=1e6;S.mode='drill';S.x=0;S.depth=0;T.EV('step',1);for(let i=0;i<40;i++){S.depth+=1;T.EV('step',1)}eq(S.lamps.length,5);eq(S.cash,1e6-5*800);ok(S.lamps.every(l=>l[2]===1));for(let i=1;i<S.lamps.length;i++)ok(Math.abs(S.lamps[i][1]-S.lamps[i-1][1]-8)<1e-6)});
t('lámpák: a már megvilágított szakaszon nem ismétel, új helyen igen',()=>{const g=boot(),T=g.T,S=T.S,L=g.sb.LMP;S.cash=1e6;S.mode='drill';const drill=(x)=>{S.x=x;S.depth=0;L.px=null;L.dist=0;T.EV('step',1);for(let i=0;i<40;i++){S.depth+=1;T.EV('step',1)}};drill(0);eq(S.lamps.length,5);drill(3);eq(S.lamps.length,5,'párhuzamos, 3 m-re: már fényes');drill(30);eq(S.lamps.length,10)});
t('lámpák: kikapcsolható, pénz nélkül nem telepít, utólag sem lóg a régi',()=>{const g=boot(),T=g.T,S=T.S,L=g.sb.LMP;S.mode='drill';S.set.alp=0;S.cash=1e6;T.EV('step',1);for(let i=0;i<20;i++){S.depth+=1;T.EV('step',1)}eq(S.lamps.length,0);S.set.alp=1;S.cash=100;L.px=null;L.dist=0;S.depth=0;T.EV('step',1);for(let i=0;i<20;i++){S.depth+=1;T.EV('step',1)}eq(S.lamps.length,0)});
t('mentés-migráció 3→4: a régi járatok lámpát kapnak, térköz ≥ 5,5 m',()=>{const g=boot({store:{drillup1:legacy({v:3,tn:[[0,0,0,100],[0,100,40,100]]})}}),S=g.T.S;ok(S.lamps.length>=14&&S.lamps.length<=20,'lámpák '+S.lamps.length);for(let i=0;i<S.lamps.length;i++)for(let j=i+1;j<S.lamps.length;j++)ok(Math.hypot(S.lamps[i][0]-S.lamps[j][0],S.lamps[i][1]-S.lamps[j][1])>=5.5);eq(S.v,g.sb.Save.VER);eq(S.set.alp,1);eq(S.set.abk,1)});
t('mentés-ellenőrzés: hibás lámpa/járat adatok kiszűrve, túl hosszú lista levágva',()=>{const g=boot({store:{drillup1:legacy({lamps:[[1,2]],tn:Array.from({length:3100},(_,i)=>[0,i,0,i+1])})}}),S=g.T.S;eq(S.lamps,[]);eq(S.tn.length,3000)});
t('gép elvesztésekor a járatok és a lámpák megmaradnak',()=>{const g=boot(),T=g.T,S=T.S;S.tn=[[0,0,0,50]];S.lamps=[[0,8,1]];S.depth=40;T.strand('teszt');eq(S.tn.length,1);eq(S.lamps.length,1);eq(S.depth,0)});
t('a lámpák terhelik a generátort',()=>{const g=boot(),T=g.T,S=T.S,G=g.sb.GEN;const a=G.demand();S.lamps=Array.from({length:200},(_,i)=>[i,0,0]);ok(G.demand()>a+9)});
t('kezelőfelület: fék gomb a sorban, 7 oszlop; a rajz hibátlan szabadesés + fékezés közben',()=>{const g=shaft([[0,0,0,300]],{abk:0}),T=g.T,S=T.S;ok(/id="bBK"/.test(g.sb.BK.btn()));S.st='D';let e=[];e=e.concat(g.frames(100));g.sb.BK.down();e=e.concat(g.frames(80));g.sb.BK.up();e=e.concat(g.frames(60));eq(e,[])});

t('mély akna asszisztenssel: sebességkorlát 35 m/s, puha landolás; a fék hűtéséhez a motor kell',()=>{const run=en=>{const g=shaft([[0,0,0,900]]),T=g.T,S=T.S,N=g.sb.NET;if(!en){S.en=0;g.sb.ENG.rpm=0;g.sb.ENG.phase='off'}S.st='D';let vmax=0,started=false,tmax=0;const r=until(g,()=>{vmax=Math.max(vmax,N.vz);tmax=Math.max(tmax,N.bkT);if(N.falling)started=true;return started&&!N.falling},4000);return{S,vmax,tmax,hp:S.hp,d:S.depth,errs:r.errs}};
 const a=run(true),b=run(false);eq(a.errs,[]);ok(a.vmax>25&&a.vmax<=37,'max sebesség '+a.vmax.toFixed(1));ok(a.tmax<1,'motoros hűtés mellett a fék nem fut túl: '+a.tmax.toFixed(2));eq(a.hp,100);ok(Math.abs(a.d-900)<.01);ok(b.tmax>a.tmax*1.5,'motor nélkül jobban melegszik: '+b.tmax.toFixed(2)+' vs '+a.tmax.toFixed(2))});

group('H) 3. fázis: fúrófej-kopás, javítás, csere, tartalék');
const drillG=(o={})=>{const g=boot();g.engineOn();const S=g.T.S;S.fuel=800;S.cash=o.cash===undefined?5e6:o.cash;S.set.sc=o.sc||10;S.set.auto=0;S.set.arc=0;if(o.f!==undefined){S.u.f=o.f;S.hf=o.f}return g};
t('új játék: hw=0, hf=0, hs=[]; régi mentés migrálva (hf = a fej szintje)',()=>{const g=boot();eq([g.T.S.hw,g.T.S.hf,g.T.S.hs],[0,0,[]]);const g2=boot({store:{drillup1:legacy({u:{d:1,h:1,t:1,c:1,f:2,g:0}})}});eq([g2.T.S.hw,g2.T.S.hf,g2.T.S.hs],[0,2,[]]);eq(g2.T.S.u.f,2)});
t('sérült kopás-adatok javítva (NaN, >100, rossz raktár)',()=>{const g=boot({store:{drillup1:legacy({v:5,hw:500,hf:'x',hs:[[0,10],[99,5],'x',[1,NaN],[2,150]]})}}),S=g.T.S;eq(S.hw,100);eq(S.hs,[[0,10],[2,100]]);const g3=boot({store:{drillup1:legacy({v:5,hw:NaN,hs:'x'})}});eq([g3.T.S.hw,g3.T.S.hs],[0,[]])});
t('fúrás közben nő a kopás, járatban haladva nem',()=>{const g=drillG(),S=g.T.S;g.T.go('D');g.frames(300);ok(S.depth>1);ok(S.hw>0,'kopás '+S.hw);const w=S.hw;S.tn=[[0,0,0,S.depth+50]];S.st='idle';S.mode='';S.depth=0;S.tr=[];g.T.go('D');g.frames(60);ok(Math.abs(S.hw-w)<1e-9||S.hw>=w)});
t('kemény kőzetben gyorsabban kopik, mint puhában (azonos úton)',()=>{const BIT=boot().sb.BIT;const cap=1000;ok(BIT.life(1)>0);const g=boot(),S=g.T.S,B=g.sb.BIT;S.u.f=1;S.hf=1;S.hw=0;const L1=g.T.LY[0],L2=g.T.LY[g.T.LY.length>5?5:2];B.wear(100,L1);const soft=S.hw;S.hw=0;B.wear(100,L2);ok(S.hw>soft,'kemény '+S.hw+' > puha '+soft)});
t('kopás hatása: a határ és a sebesség csökken, 0%-on nincs hatás',()=>{const g=boot(),S=g.T.S,B=g.sb.BIT;S.u.f=1;eq([B.cap(),B.spd()],[300,1]);S.hw=100;ok(B.cap()<300*.7);ok(B.spd()<.6);S.hw=50;ok(B.cap()<300&&B.cap()>195)});
t('elkopott fej: a fúrás leáll, de a ⌂ hazatérés működik',()=>{const g=drillG(),S=g.T.S;S.depth=200;S.tr=[['D',200]];S.hw=100;g.T.go('D');const e=g.frames(30);eq(e,[]);eq(S.st,'idle');ok(Math.abs(S.depth-200)<1e-6);g.T.go('H');let f=0;for(;f<900&&S.st=='H';f++)g.frames(1);eq(S.depth,0)});
t('figyelmeztetés 75%-nál és 90%-nál, egyszer-egyszer',()=>{const g=boot(),S=g.T.S,B=g.sb.BIT;S.u.f=0;S.hw=74;B.wear(5000,g.T.LY[0]);ok(S.hw>=75);ok(S.log.some(m=>/75%/.test(m)));const n=S.log.length;B.wear(.0001,g.T.LY[0]);eq(S.log.length,n)});
t('csere csak a bázison; a bázison felszerel, a régi a raktárba kerül kopásával',()=>{const g=boot(),S=g.T.S,B=g.sb.BIT;S.u.f=1;S.hf=1;S.hw=40;S.hs=[[0,10]];S.depth=100;B.install(0);eq(S.hs,[[0,10]]);eq(S.hw,40);S.depth=0;B.install(0);eq([S.u.f,S.hf,S.hw],[0,0,10]);eq(S.hs,[[1,40]])});
t('javítás: pénzt von le, kopást nullázza; pénz nélkül nem, mélyen nem',()=>{const g=boot(),S=g.T.S,B=g.sb.BIT;S.u.f=1;S.hf=1;S.hw=50;S.cash=0;B.repair(-1);eq(S.hw,50);S.cash=1e6;S.depth=50;B.repair(-1);eq(S.hw,50);S.depth=0;B.repair(-1);eq(S.hw,0);ok(S.cash<1e6&&S.cash>0);S.hs=[[1,80]];const c=S.cash;B.repair(0);eq(S.hs[0][1],0);ok(S.cash<c)});
t('tartalék vásárlás: csak bázison, csak birtokolt szint, raktár-korlát, pénzzel',()=>{const g=boot(),S=g.T.S,B=g.sb.BIT;S.cash=1e6;S.depth=30;B.buy(0);eq(S.hs.length,0);S.depth=0;B.buy(0);eq(S.hs,[[0,0]]);ok(S.cash<1e6);S.cash=1;B.buy(0);eq(S.hs.length,1);S.cash=1e9;for(let i=0;i<20;i++)B.buy(0);eq(S.hs.length,8)});
t('tartalék eladása: részleges pénz vissza, raktárból törlődik',()=>{const g=boot(),S=g.T.S,B=g.sb.BIT;S.hs=[[1,0],[1,100]];S.cash=0;B.sell(1);eq(S.hs.length,1);eq(S.cash,0);B.sell(0);ok(S.cash>0);eq(S.hs.length,0)});
t('fúrófej-fejlesztés vásárlása: új fej kopás 0, a régi a raktárba kerül',()=>{const g=boot(),S=g.T.S;S.cash=1e9;S.hw=33;g.T.buy('f');eq(S.u.f,1);eq([S.hf,S.hw],[1,0]);eq(S.hs,[[0,33]])});
t('mentés → betöltés megőrzi a kopást és a raktárat; stranded gép: kopás nullázva, raktár marad',()=>{const g=boot(),S=g.T.S;S.hw=42;S.hs=[[0,5],[1,60]];g.T.save();const g2=boot({store:g.store});eq([g2.T.S.hw,g2.T.S.hs],[42,[[0,5],[1,60]]])});
t('műhely-felület és fej-panel kivétel nélkül felépül',()=>{const g=boot(),S=g.T.S;S.hs=[[0,50]];S.hw=20;const h=g.sb.BIT.html();ok(/Fúrófej-raktár/.test(h)&&/Felszerel/.test(h));g.T.sheetT='head';ok(/Kopás/.test(g.T.sheetHTML()));eq(g.frames(10),[])});
t('rajzolás kopott fejjel kivétel nélkül',()=>{const g=boot(),S=g.T.S;for(const w of[0,50,100]){S.hw=w;eq(g.frames(5),[])}});

group('I) 4. fázis: depó, szalag, vonat, ürítés, tömörítés, épületek');
const depG=(o={})=>{const g=boot();g.engineOn();const S=g.T.S;S.depth=0;S.x=0;S.st='idle';S.cash=o.cash===undefined?5e7:o.cash;S.cg=o.cg||{'Homok':500,'Kavics':300};S.cq={};S.fin=o.fin||{};S.set.sc=1;if(o.b!==undefined)S.bd.b=o.b;return g};
const sumK=x=>Object.values(x).reduce((a,b)=>a+b,0);
t('új játék és régi mentés: a depó mezői megvannak, ',()=>{const g=boot(),S=g.T.S;eq([S.dp,S.dq,S.dpf,S.cq,S.bd,S.tw],[{},{},{},{},{s:0,b:0,v:0,m:0},null]);const g2=boot({store:{drillup1:legacy()}}),S2=g2.T.S;eq([S2.dp,S2.bd,S2.tw],[{},{s:0,b:0,v:0,m:0},null]);eq(S2.cg['Kőszén'],12.5);eq(S2.cash,123456)});
t('sérült depó-adatok javítva',()=>{const g=boot({store:{drillup1:legacy({v:6,dp:{'Homok':50,'Nincs ilyen':5,'Kavics':-3},dq:{'Homok':9,'Kavics':.5},dpf:{'Római ezüstdénár':2.7,'x':1},cq:{'Homok':999},cg:{'Homok':100},bd:{s:99,b:-1,v:'x',m:2},tw:{t0:1,t1:0,kg:1,cash:1}})}}),S=g.T.S;
 eq(S.dp,{'Homok':50});eq(S.dq,{'Homok':1});eq(S.dpf,{'Római ezüstdénár':2});eq(S.cq,{'Homok':100});eq(S.bd,{s:6,b:0,v:0,m:2});eq(S.tw,null)});
t('megtelt raktér leállítja a fúrást; a tömörítés helyet szabadít, utána tovább lehet fúrni',()=>{const g=boot();g.engineOn();const S=g.T.S;S.set.sc=3600;S.set.auto=0;S.fuel=800;S.cash=5e7;S.cg={'Homok':1990};g.T.go('D');g.frames(300);eq(S.st,'idle');ok(sumK(S.cg)<=2000+1e-6&&sumK(S.cg)>1999,'kg '+sumK(S.cg));const d1=S.depth;g.sb.DEP.compress();ok(g.sb.DEP.room()>600,'szabad hely '+g.sb.DEP.room());g.T.go('D');g.frames(600);ok(S.depth>d1+1,'tovább fúrt: '+S.depth.toFixed(2)+' > '+d1.toFixed(2))});
t('tömörítés: csak álló gépnél, helyet szabadít (35%), az érték csökken, a kg marad',()=>{const g=depG(),S=g.T.S,D=g.sb.DEP;const u0=D.used();D.compress();eq(sumK(S.cg),800);ok(Math.abs(D.used()-800*.65)<1e-6,'foglalt '+D.used());ok(u0-D.used()>=279.9);eq(S.cq,{'Homok':500,'Kavics':300});S.st='D';const before=JSON.stringify(S.cq);S.cq={};D.compress();eq(S.cq,{});S.st='idle'});
t('tömörítés után a friss ásvány tömörítetlen marad, a cq ≤ cg',()=>{const g=depG(),S=g.T.S,D=g.sb.DEP;D.compress();D.add('Homok',100);eq(S.cg['Homok'],600);eq(S.cq['Homok'],500);S.cg['Homok']=200;D.clampCq();eq(S.cq['Homok'],200)});
t('kirakodás: csak a bázison; a szalag kg/s sebességgel visz, a rakomány a depóba kerül',()=>{const g=depG(),S=g.T.S,D=g.sb.DEP;S.depth=50;D.start();eq(D.job,false);S.depth=0;D.start();eq(D.job,true);let f=0;for(;f<3000&&D.job;f++)g.frames(1);const sec=f*.0167;ok(sec>800/60*.8&&sec<800/60*1.25+.5,'idő '+sec.toFixed(1)+' mp (várt ≈13)');eq(S.cg,{});ok(Math.abs(sumK(S.dp)-800)<1e-6,'összeg '+sumK(S.dp));ok(Math.abs(S.dp.Homok-500)<1e-6);ok(S.dq.Homok===1)});
t('kirakodás megszakad, ha a gép elindul; a rakomány nem vész el',()=>{const g=depG(),S=g.T.S,D=g.sb.DEP;D.start();g.frames(60);ok(D.job);const moved=sumK(S.dp);ok(moved>0&&moved<800);S.st='R';g.frames(3);eq(D.job,false);ok(Math.abs(sumK(S.cg)+sumK(S.dp)-800)<1e-6,'a kg összeg megmarad')});
t('gyorsabb szalag-szint rövidebb idő; telt raktártelep megállítja a kirakodást',()=>{const g=depG({b:3}),S=g.T.S,D=g.sb.DEP;D.start();let f=0;for(;f<400&&D.job;f++)g.frames(1);ok(f<=25,'2500 kg/s: '+f+' képkocka');const g2=depG({cg:{'Homok':9000}}),S2=g2.T.S,D2=g2.sb.DEP;S2.dp={'Kavics':4000};S2.dq={'Kavics':1};D2.start();for(let i=0;i<4000&&D2.job;i++)g2.frames(1);eq(D2.job,false);ok(sumK(S2.dp)<=5000+1e-6,'a depó kapacitása: '+sumK(S2.dp));ok(sumK(S2.cg)>0,'a maradék a gépen')});
t('tömörített anyag minősége a depóban 88%, vegyes tételnél súlyozott átlag',()=>{const g=depG({b:3,cg:{'Homok':1000}}),S=g.T.S,D=g.sb.DEP;D.compress();D.add('Homok',1000);D.start();for(let i=0;i<400&&D.job;i++)g.frames(1);ok(Math.abs(S.dq.Homok-(1000*.88+1000)/2000)<1e-6,'q='+S.dq.Homok)});
t('tárolás romlik: napi 1,5%, 75%-nál megáll; frissen kirakott anyag nem',()=>{const g=depG(),S=g.T.S,D=g.sb.DEP;S.dp={'Homok':100};S.dq={'Homok':1};S.dT=g.now();g.advance(4*864e5);D.age();ok(Math.abs(S.dq.Homok-(1-.06))<1e-3,'4 nap: '+S.dq.Homok);g.advance(100*864e5);D.age();eq(S.dq.Homok,.75);S.dq.Homok=.5;g.advance(864e5);D.age();eq(S.dq.Homok,.5,'a tömörítésből adódó alacsonyabb érték nem emelkedik')});
t('vonat: eladás kifizet indulásnál, a készlet fogy, úton nem lehet újra, visszaér',()=>{const g=depG(),S=g.T.S,D=g.sb.DEP;S.dp={'Homok':500,'Kavics':300};S.dq={'Homok':1,'Kavics':1};S.cash=1000;const pl=D.plan();ok(pl.cash>0&&pl.kg===800);D.ship();eq(S.dp,{});ok(Math.abs(S.cash-1000-pl.cash)<1e-6);ok(D.trainAway());const c=S.cash;S.dp={'Homok':10};S.dq={'Homok':1};D.ship();eq(S.cash,c);ok(g.toasts.some(m=>/úton van/.test(m)));g.advance(91e3);ok(!D.trainAway());D.ship();ok(S.cash>c)});
t('vonat: a kapacitásig visz, a legdrágább anyagot előre; a maradék marad',()=>{const g=depG(),S=g.T.S,D=g.sb.DEP;S.dp={'Homok':2000,'Vasérc':2000};S.dq={'Homok':1,'Vasérc':1};const pl=D.plan();eq(pl.kg,3000);const vas=pl.out.find(e=>e.n=='Vasérc'),hom=pl.out.find(e=>e.n=='Homok');ok(vas&&vas.take===2000,'a vasérc előre');ok(hom&&hom.take===1000);D.ship();eq(S.dp,{'Homok':1000})});
t('vonat: a minőség az árat csökkenti (tömörített/öregedett anyag olcsóbb)',()=>{const g=depG(),S=g.T.S,D=g.sb.DEP;S.dp={'Homok':100};S.dq={'Homok':1};const a=D.plan().cash;S.dq.Homok=.8;const b=D.plan().cash;ok(Math.abs(b/a-.8)<1e-9)});
t('leletek: a depóba kirakodva, onnan adhatók el (múzeum)',()=>{const g=depG({cg:{},fin:{'Római ezüstdénár':3}}),S=g.T.S,D=g.sb.DEP;D.start();ok(D.job);for(let i=0;i<200&&D.job;i++)g.frames(1);eq(S.fin,{});eq(S.dpf,{'Római ezüstdénár':3});const c=S.cash;D.ship();eq(S.cash-c,3*8e3)});
t('régi sell() már a vonatot hívja; a Piac fül helyén a Depó áll',()=>{const g=depG(),S=g.T.S;eq(g.T.names[3].includes('Depó'),true);ok(!g.T.names.some(n=>/Piac/.test(n)));S.dp={'Homok':100};S.dq={'Homok':1};const c=S.cash;g.T.sell();ok(S.cash>c);g.T.tab=3;g.T.view();ok(g.sb.DEP.html().includes('Tehervonat'))});
t('épületek: bázison, pénzzel, szintenként; a hatás érezhető; maximumon megáll',()=>{const g=depG({cash:1e12}),S=g.T.S,D=g.sb.DEP;S.depth=40;D.upgrade('b');eq(S.bd.b,0);S.depth=0;D.upgrade('b');D.upgrade('s');D.upgrade('v');D.upgrade('m');eq(S.bd,{s:1,b:1,v:1,m:1});S.cash=1e12;ok(D.BLD.b.v[1]>D.BLD.b.v[0]&&D.BLD.m.v[1]<D.BLD.m.v[0]);for(let i=0;i<20;i++)D.upgrade('s');eq(S.bd.s,6);S.cash=0;S.bd.b=2;D.upgrade('b');eq(S.bd.b,2)});
t('a gép elvesztése: rakomány és tömörítés elvész, a depó/vonat/épületek megmaradnak',()=>{const g=depG(),S=g.T.S;S.dp={'Homok':77};S.dq={'Homok':.9};S.bd.s=2;S.tw={t0:g.now(),t1:g.now()+5e4,kg:1,cash:1};g.sb.DEP.compress();g.T.strand('teszt');eq([S.cg,S.cq],[{},{}]);eq(S.dp,{'Homok':77});eq(S.bd.s,2);ok(S.tw)});
t('mentés → betöltés: depó, minőség, vonat, épületek, tömörítés megmarad',()=>{const g=depG(),S=g.T.S;S.dp={'Homok':77};S.dq={'Homok':.9};S.dpf={'Őskori cserépedény':2};S.bd={s:2,b:1,v:3,m:1};S.tw={t0:g.now(),t1:g.now()+5e4,kg:5,cash:9};g.sb.DEP.compress();g.T.save();const g2=boot({store:g.store,now:g.now()+1000}),S2=g2.T.S;eq([S2.dp,S2.dq,S2.dpf,S2.bd],[S.dp,S.dq,S.dpf,S.bd]);eq(S2.cq,S.cq);eq(S2.tw.kg,5)});
t('Depó fül, Raktár fül, rajz és világ-jelenet: minden vonatfázisban kivétel nélkül',()=>{const g=depG(),S=g.T.S,D=g.sb.DEP;S.dp={'Homok':500};S.dq={'Homok':1};g.T.tab=3;g.T.view();let e=g.frames(20);D.ship();for(let i=0;i<30;i++){g.advance(3e3);e=e.concat(g.frames(2))}g.T.tab=2;g.T.view();e=e.concat(g.frames(5));g.T.tab=0;S.depth=0;e=e.concat(g.frames(10));eq(e,[]);ok(g.T.vs[2]().includes('Tömörítés'))});
t('a depó modul nélkül is elindul és játszható',()=>{const g=boot({skip:['js/depot.js']});ok(!g.sb.DEP);g.engineOn();const S=g.T.S;S.fuel=500;S.set.arc=0;g.T.go('D');eq(g.frames(60),[]);ok(S.depth>0);g.T.tab=3;g.T.view()});
const rngI=seed=>{let a=seed>>>0;return()=>{a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}};
for(const seed of [11,12,13]){t('depó-fuzz #'+seed+': véletlen fúrás/tömörítés/ürítés/eladás/fejlesztés, az invariánsok megmaradnak',()=>{const R=rngI(seed),g=boot(),S=g.T.S,D=g.sb.DEP;g.engineOn();S.cash=1e9;S.fuel=800;S.set.sc=60;let errs=[];
 for(let f=0;f<1500;f++){if(f%20===0){const a=R();if(a<.2)g.T.go(['D','U','R','L','H','idle'][(R()*6)|0]);else if(a<.3)D.compress();else if(a<.45)D.start();else if(a<.5)D.stop();else if(a<.6)D.ship();else if(a<.7)D.upgrade('sbvm'[(R()*4)|0]);else if(a<.78){S.depth=0;S.x=0;S.st='idle'}else if(a<.85)g.advance(R()*40e3);else if(a<.9){S.fin['Római ezüstdénár']=(S.fin['Római ezüstdénár']||0)+1}else if(a<.93)S.fuel=800}
  errs=errs.concat(g.frames(1));
  if(f%100===0){const fin=v=>typeof v==='number'&&isFinite(v);ok(Object.values(S.cg).concat(Object.values(S.cq),Object.values(S.dp),Object.values(S.dq)).every(v=>fin(v)&&v>=0),'értékek @'+f);ok(Object.keys(S.cq).every(n=>S.cq[n]<=(S.cg[n]||0)+1e-6),'cq≤cg @'+f);ok(Object.values(S.dq).every(v=>v>=.3&&v<=1),'minőség @'+f);ok(D.stock()<=D.BLD.s.v[S.bd.s]+1e-6,'depó-kapacitás @'+f);ok(fin(S.cash)&&S.cash>=0,'pénz @'+f)}}
 eq(errs,[]);g.T.save();ok(boot({store:g.store}).T.S.v===g.sb.Save.VER)})}

group('J) Kanyar, fék, blueprint, fúrófej-katalógus, közeli nézet');
const shaftJ=(tn,o={})=>{const g=boot();g.engineOn();const S=g.T.S;S.tn=tn;S.fuel=800;S.set.sc=o.sc||1;S.set.abk=o.abk===undefined?1:o.abk;S.depth=o.d||0;S.x=o.x||0;S.tr=S.depth>0?[['D',S.depth]]:[];S.cg={};return g};
t('kanyar: az akna alja és a vízszintes járat között (≈2,2 m süllyedés) asszisztens nélkül sem sebez',()=>{const g=shaftJ([[0,0,0,20],[0,20,60,20]],{d:20,abk:0}),S=g.T.S,N=g.sb.NET;S.st='D';let n=0;for(;n<300&&!(N.falling===false&&n>5);n++)g.frames(1);g.frames(60);eq(S.hp,100);ok(Math.abs(S.depth-22.2)<.06||Math.abs(S.depth-20)<.3,'mélység '+S.depth);ok(!S.log.some(m=>/Becsapódás/.test(m)))});
t('valódi esés (>3 m) továbbra is sebez; rövid, ≤3 m-es esés soha',()=>{const hit=h=>{const g=shaftJ([[0,0,0,h]],{abk:0}),S=g.T.S,N=g.sb.NET;S.st='D';for(let i=0;i<800&&!(S.depth>h*.9&&!N.falling);i++)g.frames(1);return S.hp};ok(hit(5)<100,'5 m: sebez');eq(hit(2.5),100)});
t('járatban fordulás közben a gép halad (ív), nem áll meg; kőzetben a régi viselkedés (áll a fordulásig)',()=>{const g=shaftJ([[0,0,0,60],[0,50,80,50]],{d:30}),T=g.T,S=T.S,N=g.sb.NET;S.st='D';for(let i=0;i<900&&!(i>10&&!N.falling);i++)g.frames(1);ok(!N.falling&&S.depth>48,'leért a járatba: '+S.depth.toFixed(1));S.st='idle';T.go('R');g.frames(40);ok(S.x>.4,'ívben halad (lefelé→jobbra kanyar): x='+S.x.toFixed(2));
 const g2=boot();g2.engineOn();const S2=g2.T.S;S2.fuel=800;S2.set.sc=1;S2.depth=100;S2.tr=[['D',100]];g2.T.go('D');g2.frames(40);g2.T.go('R');g2.frames(8);ok(Math.abs(S2.x)<.5,'kőzetben nem indul azonnal: '+S2.x)});
t('kanyar: a haladás közbeni forgás nem nyúl a depóhoz/rakományhoz; a hp nem csökken',()=>{const g=shaftJ([[0,0,0,60],[0,50,80,50]],{d:40}),T=g.T,S=T.S;S.cg={'Homok':100};for(const d of['U','D','R','L','R']){T.go(d);g.frames(25)}eq(S.hp,100);ok(S.cg.Homok>=100-1e-9)});
t('fék: nyomva tartva lassít, de a gép nem áll meg a levegőben (tovább süllyed); felengedve újra gyorsul',()=>{const g=shaftJ([[0,0,0,400]],{abk:0}),S=g.T.S,N=g.sb.NET,B=g.sb.BK;S.st='D';g.frames(150);const v0=N.vz;ok(v0>15);B.down();g.frames(240);const d1=S.depth,vb=N.vz;ok(vb<v0*.6,'lassult '+vb.toFixed(1));ok(vb>=1.5,'nem áll '+vb.toFixed(2));ok(N.falling);g.frames(60);ok(S.depth>d1+1,'tovább süllyed');B.up();g.frames(200);ok(N.vz>vb*2||!N.falling,'felengedve gyorsul')});
t('blueprint: minden egységnek saját színe, rövid neve és állapotjelzője van; a lapkák kijelölnek',()=>{const g=boot(),B=g.sb.BP;const cols=B.parts.map(p=>p.c);eq(new Set(cols).size,B.parts.length,'külön színek');ok(B.parts.every(p=>p.s&&p.u&&typeof p.v==='function'));B.pick('f');const h=B.html();ok(/bpcs/.test(h)&&/class="bpc sel"/.test(h));eq((h.match(/class="bpc(?: sel)?"/g)||[]).length,B.parts.length);ok(/→/.test(h),'előtte–utána összehasonlítás');ok(/Fúrófej élessége/.test(h));B.pick('d');ok(!/Fúrófej élessége/.test(B.html()))});
t('fúrófej-katalógus: 6 rajz, szintenként a helyes fúrható réteg-szám, felszerelt/zárolt jelölés',()=>{const g=boot(),S=g.T.S,B=g.sb.BIT;S.u.f=1;S.hf=1;const h=B.gallery();eq((h.match(/<svg/g)||[]).length,6);ok(/Felszerelve/.test(h)&&/Zárolt/.test(h)&&/Következő szint/.test(h));const can=t=>g.T.LY.filter((l,i)=>g.T.HR[i]<=g.T.HD[t][1]).length;eq(can(0),3);ok(h.includes('<b>3/11</b>')&&h.includes('<b>'+can(5)+'/11</b>'))});
t('közeli nézet és repedések: minden minőségi fokozaton és fúrófej-szinten kivétel nélkül; kikapcsolható; nem fúrás közben nem rajzol',()=>{let e=[];for(const q of['0','1','2'])for(const f of[0,3,5]){const g=boot();g.sb.Gov.setMode(q);g.engineOn();const S=g.T.S;S.u.f=f;S.hf=f;S.hw=f*15;S.fuel=800;S.depth=200;S.tr=[['D',200]];S.set.sc=10;S.set.fcl=q==='2'?0:1;g.T.go('D');e=e.concat(g.frames(90))}eq(e,[]);const g=boot();ok(!g.sb.FACE.active());g.sb.FACE.inset({x:{},w:360,h:600,ts:1});const a=g.sb.FACE.cyc(3,1.7,.5),b=g.sb.FACE.cyc(3,1.7,.5);eq(a,b);ok(a.p>=0&&a.p<1)});
t('a közeli nézet és a blueprint nélküli indulás: face.js hiányában is játszható',()=>{const g=boot({skip:['js/face.js']});ok(!g.sb.FACE);g.engineOn();g.T.S.fuel=500;g.T.S.set.arc=0;g.T.go('D');eq(g.frames(60),[]);ok(g.T.S.depth>0)});

group('K) Legrövidebb hazaút és a járatok benövése');
const loopG=()=>{const g=boot();g.engineOn();const S=g.T.S;S.tn=[[0,0,0,100],[0,100,100,100],[100,100,100,200],[100,200,0,200],[0,200,0,100]];S.tr=[['D',100],['R',100],['D',100],['L',100],['U',100]];S.x=0;S.depth=100;S.fuel=800;S.set.sc=1;S.set.auto=0;S.cg={};return g};
t('hazaút: a hurkot kihagyja – a bejárt 500 m helyett a legrövidebb 100 m',()=>{const g=loopG(),S=g.T.S,r=g.sb.RT.home();ok(r&&r.neu===100&&r.old===500,JSON.stringify(r));eq(S.tr,[['D',100]]);ok(S.log.some(m=>/Legrövidebb hazaút/.test(m)))});
t('hazaút: egyszerű, kitérő nélküli úton nem változtat (null), a verem érintetlen',()=>{const g=boot(),S=g.T.S;S.tn=[[0,0,0,50],[0,50,40,50]];S.tr=[['D',50],['R',40]];S.x=40;S.depth=50;const b=JSON.stringify(S.tr);eq(g.sb.RT.home(),null);eq(JSON.stringify(S.tr),b)});
t('hazaút: ha a gép nincs a hálózaton vagy a felszín nem elérhető, a régi út marad',()=>{const g=loopG(),S=g.T.S;S.fuel=1e-4;S.x=60;S.depth=150;const b=JSON.stringify(S.tr);eq(g.sb.RT.home(),null);eq(JSON.stringify(S.tr),b);const g2=loopG(),S2=g2.T.S;S2.fuel=1e-4;S2.tn=S2.tn.slice(1);const b2=JSON.stringify(S2.tr);eq(g2.sb.RT.home(),null);eq(JSON.stringify(S2.tr),b2)});
t('hazaút: a függőleges összeg mindig a mélység (nincs elcsúszás), több lehetséges úton a legrövidebbet választja',()=>{const g=boot(),S=g.T.S;S.tn=[[0,0,0,40],[0,40,30,40],[30,40,30,80],[0,40,0,80],[0,80,30,80]];S.tr=[['D',40],['R',30],['D',40],['L',30]];S.x=0;S.depth=80;const r=g.sb.RT.home();ok(r&&r.neu===80,JSON.stringify(r));eq(S.tr,[['D',80]]);const dv=S.tr.reduce((a,t)=>a+(t[0]=='D'?t[1]:t[0]=='U'?-t[1]:0),0);eq(dv,S.depth)});
