t('labor: a mintakép és a monitor kivétel nélkül rajzol minden szinten, minta nélkül is',()=>{const g=lg(),G=g.sb.GEO.ens(),S=g.T.S,cx=g.sb.document.createElement('canvas').getContext('2d');g.sb.LAB.paintSample(cx,200,100,null,0);for(const l of[1,2,3]){G.lab.lv=l;S.depth=3000;g.sb.LAB.busy=0;g.sb.LAB.take();g.sb.LAB.paintSample(cx,200,100,G.lab.last,.7);ok(g.sb.LAB.html().includes('Mintavétel'))}g.T.tab=0;eq(g.frames(30).length,0);g.T.tab=1;eq(g.frames(30).length,0)});
