 S.tr=[['D',100],['R',200],['D',100],['L',200],['D',100],['R',200],['D',100]];S.x=200;S.depth=400;S.tn=[[0,0,0,100],[0,100,200,100],[200,100,200,200],[200,200,0,200],[0,200,0,300],[0,300,200,300],[200,300,200,400]];
