 const h=lg(),H=h.T.S;H.u.d=4;H.fuel=1e9;H.tr=[['D',100],['R',30],['D',100]];H.x=30;H.depth=200;H.tn=[[0,0,0,100],[0,100,30,100],[30,100,30,200]];eq(h.sb.RT.home(),null);eq(H.tr.length,3);
