group('Z) Beszámolók, élethű effektek, cinematic mód');
t('beszámolók: mélységgel nőnek, egyszerre egy kártya, az átugrottak a gyűjteménybe kerülnek, mentésben megmaradnak',()=>{const g=lg(),S=g.T.S,O=g.sb.STO;ok(O&&O.DB.length>=20);S.depth=0;g.frames(3,30);eq((S.sty||[]).length,0);S.depth=100;g.frames(3,30);ok(O.has(1)&&O.has(2)&&O.has(3));ok(!O.has(4));S.depth=800;g.frames(3,30);ok(O.has(7));S.depth=13000;g.frames(3,30);ok(O.has(17)&&O.has(18));g.T.save();const h=boot({store:g.store});ok(h.T.S.sty.length>=18)});
t('beszámolók: a szöveg minden bejegyzésnél létezik, azonosítók egyediek, mélység szerint növekvő',()=>{const O=lg().sb.STO;let p=-1;const ids=new Set();for(const e of O.DB){ok(e.t&&e.s&&e.y&&e.k,'hiányzó mező #'+e.id);ok(e.d>p,'sorrend #'+e.id);p=e.d;ids.add(e.id)}eq(ids.size,O.DB.length);ok(O.html().includes('Beszámolók'))});
t('élethű effektek és cinematic: a rajz hibátlan minden minőségen, be- és kilépés rendben',()=>{const g=lg(),S=g.T.S,C=g.sb.CIN;ok(!!C);for(const q of[0,1,2]){g.sb.Gov.q=q;eq(g.frames(3,30),[])}S.set.rl=0;eq(g.frames(3,30),[]);S.set.rl=1;C.on=true;C.k=1;eq(g.frames(5,30),[]);S.depth=2400;g.frames(3,30);C.on=false;C.k=0;eq(g.frames(3,30),[])});
t('kijelzők: elrejtés/előhívás, mentésben megmarad, rejtve nem rajzolódik, a rajz hibátlan',()=>{const g=lg(),S=g.T.S,P=g.sb.PN;ok(!!P);for(const k of Object.keys(P.NAMES))ok(P.vis(k));S.depth=300;S.tr=[['D',300]];g.frames(4,30);P.set('sz',0);P.set('face',0);P.set('hull',0);ok(!P.vis('sz')&&!P.vis('face')&&!P.vis('hull'));eq(P.nHidden(),3);eq(g.frames(5,30),[]);g.T.save();const h=boot({store:g.store});ok(!h.sb.PN.vis('sz'));P.all();eq(P.nHidden(),0);eq(g.frames(3,30),[]);const O=g.sb.STO;O.cur=null;O.gap=0;P.set('sto',0);S.depth=900;g.frames(3,30);ok(O.has(7)&&!O.cur)});

group('N) Natív-app érzet');
t('manifest: érvényes, maskable ikon létezik, offline fájllista tartalmazza az új fájlokat',()=>{const fs=require('fs'),m=JSON.parse(fs.readFileSync(__dirname+'/../manifest.webmanifest','utf8'));ok(m.display==='standalone'&&m.display_override.includes('standalone')&&m.orientation==='portrait');const mk=m.icons.find(i=>i.purpose==='maskable');ok(mk&&fs.existsSync(__dirname+'/../'+mk.src));const sw=fs.readFileSync(__dirname+'/../sw.js','utf8');for(const f of['js/appshell.js','js/panels.js','js/cine.js','js/story.js','js/zoom.js','js/surface.js','icon-maskable-512.png'])ok(sw.includes(f),f)});
t('natív segédek: rezgés és párbeszéd hibátlan, a vissza-gomb nem dob hibát, nincs böngésző-felugró a kódban',()=>{const g=lg(),N=g.sb.NAT;ok(N&&typeof N.hap==='function'&&typeof N.ask==='function'&&typeof N.back==='function');N.hap(10);g.T.S.set.hap=0;N.hap(10);let hit=0;N.ask('x','ok',()=>hit++);ok(hit>=0);ok(N.back()===false||N.back()===true);const html=require('fs').readFileSync(__dirname+'/../index.html','utf8');ok(!/onclick="[^"]*confirm\(/.test(html),'confirm() maradt')});

group('M) Mérföldkövek, diagnosztika, hang');
t('mérföldkövek: elért mélységért egyszeri jutalom, nem fizet kétszer, mentésben marad',()=>{const g=lg(),S=g.T.S,L=g.sb.GL;ok(!!L);const c0=S.cash;S.max=1200;S.depth=1200;L.check();ok(L.has('d100')&&L.has('d1k'));const c1=S.cash;ok(c1>c0);L.check();eq(S.cash,c1);g.T.save();const h=boot({store:g.store});ok(h.sb.GL.has('d1k'));ok(L.html().includes('Mérföldkövek'))});
t('mérföldkövek: gyűjtemény-jutalom a beszámolók száma szerint',()=>{const g=lg(),S=g.T.S,L=g.sb.GL;S.sty=[1,2,3,4,5];const c0=S.cash;L.check();ok(L.has('c5')&&S.cash>c0)});
t('diagnosztika: képességek lekérdezése hibátlan, a szöveg a mért adatból áll',()=>{const g=lg(),D=g.sb.DIAG;ok(!!D);const c=D.caps();ok(c.dpr>0);const r=Object.assign(c,{fps:60,avgMs:16.7,p95Ms:20,maxMs:30,frames:300,qStart:2,ver:'x',depth:0,save:1,verdict:'ok'});ok(D.text(r).includes('FPS: 60'))});
t('fúróhang: a rajz/hang-lépés kemény és puha kőzetben is hibátlan',()=>{const g=lg(),S=g.T.S;for(const d of[10,5000,60000]){S.depth=d;S.tr=[['D',d]];g.T.go('D');eq(g.frames(8,30),[])}});

group('T) Tanterem (előadás-mód)');
t('tanterem: a diasor felépül a gép aktuális adataiból, minden dia teljes, csak álló gépnél indul, kilépés rendben',()=>{const g=lg(),S=g.T.S,L=g.sb.LEC;ok(!!L);S.sty=[1,2,3];g.sb.GEO.ens().sz.lv=1;const l=L.build();ok(l.length>=30,'diák '+l.length);for(const e of l){ok(e.t&&e.s&&e.k&&e.sub&&e.f&&e.dur>=8,'dia: '+e.t)}ok(l.some(e=>e.sub.includes('Meghajtás')));ok(l.some(e=>e.sub.includes('Lánctalp')));ok(l.some(e=>e.sub.includes('Szeizmográf')));
 S.st='D';L.start();ok(!L.on,'mozgó gépnél nem indul');S.st='idle';const C=g.sb.CIN;L.start();ok(!L.on||C.on);if(L.on){eq(g.frames(6,100),[]);ok(C.cap&&C.cap.t);const i0=L.i;C.capT=999;g.frames(3,100);ok(L.i!==i0,'léptet')}C.exit();g.frames(2,30);ok(!L.on&&!C.on)});
t('mászás-fizika: a lejtő a gépet visszacsúsztatja, ha a tapadás kevés (a szimulációban a gyenge gép nem jut át)',()=>{const g=lg(),S=g.T.S,H=g.sb.HILL;S.u.d=0;const c=g.T.calc();let sl=0;for(let x=400;x<900;x+=2){const r=H.drive(c,x,1,5);sl=Math.max(sl,r.s)}ok(sl>0,'van csúszási szakasz')});

group('U) Statisztika, távollét-összegzés, mentési emlékeztető');
t('statisztika: az S.ss mezői pótlódnak, a fúrt méter/bevétel/kiadás számlálódik, a rekord mentéssel megmarad',()=>{const g=lg(),S=g.T.S,ST=g.sb.ST;ok(!!ST);S.ss=undefined;ST.init();ok(S.ss&&S.ss.dm===0&&S.ss.t0>0);
 S.st='D';S.depth+=40;S.cash+=5000;ST.onSim(1);ok(S.ss.dm===40&&S.ss.ce===5000&&S.ss.bs===5000);S.cash-=2000;ST.onSim(1);ok(S.ss.cs===2000);
 ok(ST.html().includes('Pályafutás'));g.T.save();const g2=boot({store:g.store});ok(g2.T.S.ss&&g2.T.S.ss.dm===40,'mentés után is megvan')});
t('távollét: hosszú szünet után összegzés készül a tényleges változásokból; rövid szünetnél nem',()=>{const g=lg(),S=g.T.S,ST=g.sb.ST;ST.init();S.st='idle';S.depth+=120;S.cash+=7e4;S.fuel-=50;ST.onSim(3600);const a=S.ss.aw;ok(a&&a.s===3600&&Math.round(a.dd)===120&&Math.round(a.dc)===7e4&&Math.round(a.df)===-50,JSON.stringify(a));
 ok(ST.awayHtml(a).includes('120')); const old=S.ss.aw;S.depth+=5;ST.onSim(2);ok(S.ss.aw===old,'rövid szünet nem ír felül')});
t('valódi szimuláció: fúrás közben eltelt idő (régi S.t) után van összegzés, és hiba nélkül fut',()=>{const g=lg(),S=g.T.S,ST=g.sb.ST;ST.init();S.cash=5e6;S.fuel=500;g.T.go('D');g.frames(5,50);S.t-=1800e3;eq(g.frames(10,50),[]);ok(S.ss.aw&&S.ss.aw.s>=1000,'aw='+JSON.stringify(S.ss.aw))});
t('mentési emlékeztető: csak akkor kell, ha van mit veszíteni és régen volt export; az export frissíti',()=>{const g=lg(),S=g.T.S,ST=g.sb.ST;ST.init();S.max=0;ok(!ST.needsBackup());S.max=500;S.ss.t0-=9*864e5;ok(ST.needsBackup());ST.markExport();ok(!ST.needsBackup())});

group('V) Lánctalp-kopás');
t('lánctalp: a megtett úttól kopik (meredeken gyorsabban), a tapadás romlik, de legfeljebb 35%-ot',()=>{const g=lg(),S=g.T.S,Wr=g.sb.WEAR,H=g.sb.HILL;ok(!!Wr);S.tk=undefined;eq(Wr.tk(),0);ok(Math.abs(Wr.mf()-1)<1e-9);const m0=H.mu();
 S.depth=0;S.x=100;Wr.add(1000);const flat=S.tk;ok(flat>0&&flat<6,'sík: '+flat);S.tk=0;S.x=700;const sf=Wr.slopeF();ok(sf>1.5,'meredek szorzó '+sf);Wr.add(1000);ok(S.tk>flat,'meredeken gyorsabb');
 S.tk=100;ok(Math.abs(Wr.mf()-.65)<1e-9);ok(H.mu()<m0*.66+1e-9&&H.mu()>0,'mu '+H.mu());S.tk=50;ok(H.mu()<m0&&H.mu()>m0*.65)});
t('lánctalp: a step eseménytől kopik, menti a mentés, a bázison felújítható a költségért, máshol nem',()=>{const g=lg(),S=g.T.S,Wr=g.sb.WEAR;S.tk=0;S.depth=0;Wr.prevX=null;Wr.step();for(let i=0;i<10;i++){S.x+=40;Wr.step()}ok(S.tk>0,'kopott');g.T.save();const g2=boot({store:g.store});ok(g2.T.S.tk>0,'mentés után is');
 S.x=0;S.st="idle";S.tk=40;S.cash=1e9;const c=Wr.cost();ok(c>0);const c0=S.cash;Wr.repair();ok(S.tk===0&&Math.abs(c0-S.cash-c)<1,'felújítva');S.tk=30;S.depth=500;Wr.repair();ok(S.tk===30,'a mélyben nem')});
t('lánctalp: a kopott gép a domb-szimulációban rosszabbul teljesít, az új változatlan; a panel megjelenik',()=>{const g=lg(),S=g.T.S,H=g.sb.HILL,Wr=g.sb.WEAR;S.u.d=2;const c=g.T.calc();let a=0,b=0;S.tk=0;for(let x=400;x<900;x+=2)a=Math.max(a,H.drive(c,x,1,5).s);S.tk=100;for(let x=400;x<900;x+=2)b=Math.max(b,H.drive(c,x,1,5).s);ok(b>=a,'kopottan legalább akkora csúszás '+a+' → '+b);ok(Wr.html().includes('Lánctalp'))});

group('W) Kihívások és testreszabás');
t('kihívások: napi 3 + heti 2 készül, ugyanarra a napra ugyanaz; a haladás a számlálókból jön, teljesítéskor jutalom jár egyszer',()=>{const g=lg(),S=g.T.S,Q=g.sb.QS,ST=g.sb.ST;ok(!!Q);ST.init();S.qs=undefined;Q.roll();ok(S.qs.d.length===3&&S.qs.w.length===2);ok(new Set(S.qs.d.map(q=>q.k)).size===3,'különböző típusok');
 const k=Q.keys(),a=JSON.stringify(Q.make(k.dk,false,3).map(q=>q.k)),b=JSON.stringify(Q.make(k.dk,false,3).map(q=>q.k));eq(a,b);
 for(const q of S.qs.d.concat(S.qs.w)){ok(q.t>0&&q.r>0&&isFinite(q.b))}
 const q=S.qs.d[0],c0=S.cash;const o=ST.ss();o[q.k==='dm'?'dm':q.k==='ce'?'ce':q.k==='tr'?'tr':'hm']=(o[q.k]||0)+q.t+1;Q.check();ok(q.d===1&&S.cash>=c0+q.r,'jutalom');const c1=S.cash;Q.check();ok(S.cash===c1,'nem fizet kétszer');ok(Q.html().includes('Kihívások'))});
t('kihívások: új napnál/hétnél újrasorsolódik, a régi mentésből hiba nélkül indul, mentéssel megmarad',()=>{const g=lg(),S=g.T.S,Q=g.sb.QS;Q.roll();S.qs.dk='1999-1-1';S.qs.d.forEach(q=>q.d=1);Q.roll();ok(S.qs.d.every(q=>!q.d),'új nap');S.qs.wk='w1';Q.roll();ok(S.qs.w.every(q=>!q.d));g.T.save();const g2=boot({store:g.store});ok(g2.T.S.qs&&g2.T.S.qs.d.length===3)});
t('testreszabás: alapból minden ingyenes változat, vásárlás levon és megjegyez, a bázison kívül nem, a rajz hibátlan minden festésben',()=>{const g=lg(),S=g.T.S,P=g.sb.PNT;ok(!!P);S.pt=undefined;ok(P.st().c==='alap'&&P.hc(['a','b'])[0]==='a');S.x=0;S.depth=0;S.st='idle';S.cash=1e6;P.buy('c','piros');ok(S.pt.c==='piros'&&S.cash===1e6-40e3&&P.hc(['a','b'])[0]==='#e0503f');P.buy('c','alap');ok(S.pt.c==='alap'&&S.cash===1e6-40e3);P.buy('c','piros');ok(S.cash===1e6-40e3,'másodszor ingyen');
 S.cash=1;P.buy('s','figy');ok(S.pt.s==='nincs','pénz nélkül nem');S.cash=1e6;S.depth=500;P.buy('l','hideg');ok(S.pt.l==='alap','mélyben nem');S.depth=0;
 for(const c of P.T.c)for(const s of P.T.s){S.pt.own=['c:'+c[0],'s:'+s[0],'l:hideg','l:boros'];S.pt.c=c[0];S.pt.s=s[0];S.pt.l=['alap','hideg','boros'][(c[0].length+s[0].length)%3];eq(g.frames(2,30),[])}
 ok(P.html().includes('Testreszabás'))});

group('X) Ambiens hang és teljesítmény-figyelő');
t('ambiens hang: a rétegek a mélységgel értelmesen változnak (felszín: szél; mély: zúgás, hőség; mag: lüktetés), AC nélkül hibátlan',()=>{const g=lg(),A=g.sb.AMB;ok(!!A);const s=A.mix(0),m=A.mix(5e3),h=A.mix(300e3),c=A.mix(4e6);ok(s.wind>0&&s.hum===0&&s.hiss<.2);ok(m.wind===0&&m.hum>0);ok(h.hiss>m.hiss&&h.f<m.f);ok(c.thump>0&&A.mix(1e6).thump===0);
 for(const d of[0,1,1e3,1e6,6.3e6,-5,NaN]){const r=A.mix(d);for(const k in r)ok(isFinite(r[k])&&r[k]>=0,k+' @'+d)}eq(g.frames(20,100),[])});
t('ambiens hang: hangkörnyezettel a csomópontok létrejönnek, a kikapcsolás/némítás lenullázza, a hiba nélkül fut',()=>{const g=lg(),S=g.T.S,A=g.sb.AMB;
 const mkP=()=>({value:0,setTargetAtTime(v){this.value=v}}),node=()=>({gain:mkP(),frequency:mkP(),Q:mkP(),connect(){},start(){},type:''});
 g.sb.__fa={state:'running',currentTime:0,destination:{},createBufferSource:()=>Object.assign(node(),{buffer:null,loop:false}),createBiquadFilter:node,createGain:node,createOscillator:node};require('vm').runInContext('AC=__fa;NB={}',g.sb);
 S.set.vol=60;S.set.amb=1;S.depth=5000;A.update();ok(A.n,'létrejött');ok(A.n.og.gain.value>0,'zúgás hallható '+A.n.og.gain.value);S.set.amb=0;A.update();ok(A.n.og.gain.value===0&&A.n.hiss.g.gain.value===0,'kikapcsolva némít');S.set.amb=1;S.set.vol=0;A.update();ok(A.n.og.gain.value===0,'hangerő 0');
 S.set.vol=60;S.depth=4e6;A.update();ok(A.n.tg.gain.value>0&&A.n.lg.gain.value>0,'mag-lüktetés')});
t('teljesítmény-figyelő: az fps az átlagolt képidőből jön; ha a minőségváltó visszavesz, számol és értesít (legfeljebb percenként)',()=>{const g=lg(),S=g.T.S,P=g.sb.PF,G=g.sb.Gov;ok(!!P);P.ema=16.7;ok(P.fps()===60);P.ema=33.3;ok(P.fps()===30);S.set.fps=1;G.setMode(2);P.q=null;P.frame(.016);ok(P.q===2);G.q=1;const p0=(S.ss&&S.ss.pd)||0;P.lastWarn=0;P.frame(.016);ok(S.ss.pd===p0+1&&P.lastWarn>0,'visszavétel számolva');G.q=0;P.frame(.016);ok(S.ss.pd===p0+2);
 for(const v of[0,.0001,.7,NaN])P.frame(v);ok(isFinite(P.ema))});

group('Y2) Szabadesés: irányítás és tájolás');
t('szabadesés közben a mozgásgombok nem állítanak át állapotot (jelzés), a stop és a fék működik; leérkezés után újra irányítható',()=>{const g=shaft([[0,0,0,300]],{abk:1}),T=g.T,S=T.S,N=g.sb.NET;S.st='D';let started=false;until(g,()=>{if(N.falling)started=true;return started},500);ok(N.falling);
 T.go('L');ok(S.st==='D','a ◀ nem írja át az állapotot esés közben: '+S.st);T.go('U');ok(S.st==='D');N.bkIn=1;T.go('idle');ok(S.st==='idle','stop mehet');N.bkIn=0;
 const r=until(g,()=>!N.falling,4000);ok(!N.falling,'leérkezett');T.go('U');ok(S.st==='U','leérkezés után újra irányítható')});
t('szabadesés: a forgókamra-kapu nem tartja félúton a gépet (esés közben nincs kamra-fúrás)',()=>{const g=shaft([[0,0,0,300]],{abk:1}),T=g.T,S=T.S,N=g.sb.NET,C=g.sb.CH;S.st='D';const n0=(S.ch||[]).length;until(g,()=>!N.falling&&S.depth>250,4000);ok((S.ch||[]).length===n0,'nem fúrt kamrát esés közben')});

group('Y3) Teljes képernyő');
t('teljes képernyő: alapból KI (nem kér, nem zavar), csak bekapcsolva kér, legfeljebb 3 másodpercenként; ha a játékos kilép, kikapcsol; a manifest sima standalone',()=>{const g=lg(),S=g.T.S,F=g.sb.FS;ok(!!F);let n=0;const de={requestFullscreen(o){n++;return Promise.resolve()}};g.sb.document=Object.assign(g.sb.document||{},{documentElement:de,fullscreenElement:null});
 S.set.fs=undefined;ok(!F.want()&&!F.req()&&n===0,'alapból nem kér');S.set.fs=1;ok(F.want()&&F.req()&&n===1);ok(!F.req()&&n===1,'3 mp-en belül nem kér újra');F.last=0;g.sb.document.fullscreenElement={};ok(!F.req()&&n===1,'már teljes képernyő');S.set.fs=0;F.last=0;g.sb.document.fullscreenElement=null;ok(!F.req()&&n===1,'kikapcsolva nem kér');
 const m=JSON.parse(require('fs').readFileSync(require('path').join(__dirname,'..','manifest.webmanifest'),'utf8'));ok(m.display==='standalone'&&!m.display_override.includes('fullscreen'))});

group('Z2) Kiérés a felszínre dombon');
t('domboldalon vízszintesen kifúrt járat: a gép kiér a felszínre, nem megy tovább a levegőben; a visszaút-verem következetes',()=>{const g=lg(),T=g.T,S=T.S,H=g.sb.HILL,R=g.sb.TER;ok(!!R);g.engineOn();S.fuel=900;S.cash=1e9;
 H.e0=90;S.e0=90;S.x=-700;S.depth=20;S.tr=[['D',20]];S.tn=[[-700,0,-700,20]];S.st='R';S.mode='travel';let hist=[];
 for(let i=0;i<4000&&S.x<-250;i++){g.frames(1,50);hist.push(S.depth);if(S.x>-700&&S.depth<.6&&R.n>0)break}
 ok(R.n>=1,'kiért (n='+R.n+')');ok(S.depth>=0&&S.depth<1,'a felszínen: '+S.depth);ok(Math.abs(S.e0-H.E(S.x))<8||Math.abs(H.e0-H.E(S.x))<8,'a szint a terephez igazodik');
 const net=S.tr.reduce((a,m)=>a+(m[0]==='D'?m[1]:m[0]==='U'?-m[1]:0),0);ok(Math.abs(net-S.depth)<.6,'verem '+net+' ≈ mélység '+S.depth)});
t('sík terepen a rendes mélység nem változik: a föld alatti vízszintes járat nem „bukkan ki"',()=>{const g=lg(),T=g.T,S=T.S,H=g.sb.HILL,R=g.sb.TER;g.engineOn();S.fuel=900;H.e0=0;S.e0=0;S.x=0;S.depth=30;S.tr=[['D',30]];S.st='R';S.mode='travel';g.frames(200,50);ok(R.n===0&&S.depth>=29.9,'mélység '+S.depth+' n='+R.n)});

group('Y4) Akna-vezetés, dugattyú-hatás, zuhanófék');
t('zuhanófék: a gomb felirata ZUHANÓFÉK, a panel és az üzenetek is így hívják',()=>{const g=lg(),B=g.sb.BK,fs=require('fs');ok(/ZUHANÓFÉK/.test(B.btn())&&/id="bBK"/.test(B.btn()));const t=fs.readFileSync(__dirname+'/../js/tunnels.js','utf8');ok(t.includes("fillText('ZUHANÓFÉK'")&&!/gombot|gombbal/.test(t.replace(/ZUHANÓFÉK gomb/g,'')),'üzenetek')});
t('akna-vezetés: esés közben az x az akna tengelyéhez simul, az imbolygás korlátos és a landolás után lecsillapodik',()=>{const g=shaft([[0,0,0,300]],{abk:1,x:.4}),T=g.T,S=T.S,N=g.sb.NET,SH=g.sb.SH;ok(!!SH);S.st='D';let mx=0,started=false;
 for(let i=0;i<4000;i++){g.frames(1,30);if(N.falling)started=true;mx=Math.max(mx,Math.abs(N.sw));if(started&&!N.falling)break}
 ok(started&&!N.falling,'leérkezett');ok(Math.abs(S.x)<.15,'tengelyen: '+S.x);ok(mx<=.0701,'lengés korlátos '+mx);g.frames(200,50);ok(Math.abs(N.sw)<.002,'lecsillapodott '+N.sw)});
t('dugattyú-hatás: a szűk aknában a légellenállás többszörös, így a zuhanás lassabb, mint szabad térben',()=>{const g=lg(),N=g.sb.NET;ok(N.piston>3&&N.piston<6,'tényező '+N.piston)});

group('G) Fuzz: véletlen kezelés, minden állapot-invariáns megmarad');
const rng=seed=>{let a=seed>>>0;return()=>{a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}};
for(const seed of [1,2,3,4,5,6]){t('fuzz #'+seed+': 2000 képkocka véletlen gombnyomással, járatokkal, esésekkel',()=>{const R=rng(seed),g=boot(),T=g.T,S=T.S,N=g.sb.NET,B=g.sb.BK,P=g.sb.PW;
 S.cash=5e7;S.fuel=800;S.set.sc=[1,10,60][seed%3];S.set.abk=seed%2;S.u.d=seed%4;S.u.h=seed%3;S.u.f=seed%3;
 // véletlen járathálózat
 S.tn=[];let x=0,d=0;for(let i=0;i<30;i++){const v=R()<.5,l=5+R()*80;if(v){S.tn.push([x,d,x,d+l]);d+=l}else{const dir=R()<.5?-1:1;S.tn.push([x,d,x+dir*l,d]);x+=dir*l}}
 const acts=['D','U','L','R','H','idle'];let errs=[];
 for(let f=0;f<2000;f++){
  if(f%25===0){const a=R();if(a<.5)T.go(acts[(R()*acts.length)|0]);else if(a<.6){B.down()}else if(a<.7){B.up()}else if(a<.75)P.toggleEng();else if(a<.8)g.sb.GEN.toggle();else if(a<.83){S.depth=Math.max(0,Math.min(300,S.depth+(R()-.5)*100));S.x+=(R()-.5)*50}else if(a<.86){S.fuel=800;S.gf=60}else if(a<.88){S.cash=5e7}}
  errs=errs.concat(g.frames(1));
  if(f%100===0){const fin=v=>typeof v==='number'&&isFinite(v);
   ok(fin(S.x)&&fin(S.depth)&&fin(S.fuel)&&fin(S.hp)&&fin(S.cash)&&fin(N.vz)&&fin(N.bk)&&fin(N.bkT),'véges értékek @'+f);
   ok(S.depth>=0&&S.depth<=6371e3,'mélység @'+f+': '+S.depth);ok(S.hp>=0&&S.hp<=100,'hp @'+f);ok(S.fuel>=0&&S.gf>=0,'üzemanyag @'+f);ok(N.vz>=0&&N.bk>=0&&N.bk<=1.0001,'fék/sebesség @'+f);
   ok(Array.isArray(S.tr)&&S.tr.every(e=>e[1]>=0&&isFinite(e[1])),'verem @'+f);ok(S.lamps.every(l=>l.every(isFinite)),'lámpák @'+f);
   ok(S.st==='idle'||'UDLRH'.includes(S.st),'állapot @'+f)}}
 eq(errs,[]);T.save();const g2=boot({store:g.store});ok(g2.T.S.tn.length>=1&&g2.T.S.v===g2.sb.Save.VER,'a fuzz utáni mentés betölthető')})}

group('Y5) Üzemanyag kifogyása: nincs automatikus átváltás');
t('kifogyott tank + van szén a raktárban: a gép megáll és jelez, a raktárhoz nem nyúl',()=>{const g=boot(),T=g.T,S=T.S;S.cg={'Kőszén':50};S.fuel=0;S.depth=30;S.x=5;S.st='D';S.en=0;g.frames(120,30);const t0=S.cg['Kőszén'];ok(S.st==='idle','megállt: '+S.st);ok(S.fuel<=1e-6,'üzemanyag 0: '+S.fuel);eq(t0,50);ok(!T.S.str,'nem ragadt be');ok(S.depth===30,'nem mozdult')});
t('jóváhagyás: irányt nyomva a gép átvált a saját tárolóra és ég a raktárból',()=>{const g=boot(),T=g.T,S=T.S;S.cg={'Kőszén':50};S.fuel=0;S.depth=30;S.x=5;S.st='idle';T.go('L');ok(S.cg['Kőszén']<50,'raktár fogyott '+S.cg['Kőszén']);ok(S.fuel>0,'tank '+S.fuel)});
t('nincs tartalék sem: a régi viselkedés (leáll/beszorul), nem történik hiba',()=>{const g=boot(),T=g.T,S=T.S;S.cg={};S.fuel=0;S.depth=30;S.x=5;S.st='D';g.frames(120,30);ok(S.fuel<=1e-6,'üres marad')});

group('Y6) Kazán és gőzrendszer (fejleszthető)');
const kz=()=>{const g=boot(),S=g.T.S,M=g.sb.STM;S.en=1;S.st='idle';S.depth=30;S.x=5;return{g,S,M,st:(real,n)=>{for(let i=0;i<n;i++)M.step(real)}}};
t('a kazán fejleszthető: U.b a Műhely listájában, 5 szint, S.u.b alapból 0, vétel növeli',()=>{const g=boot(),S=g.T.S,M=g.sb.STM;ok(!!M&&g.sb.BL.length===5);const U=g.sb.eval?0:0;eq(S.u.b|0,0);S.cash=1e9;S.depth=0;S.x=0;S.st='idle';g.sb.buy('b');eq(S.u.b,1);ok(S.cash<1e9,'fizetett')});
t('régi mentés (S.u.b nélkül) hibátlanul betöltődik és a kazán 0. szintű',()=>{const raw=legacy(),g=boot({store:{drillup1:raw}}),S=g.T.S;g.frames(30,30);ok((S.u.b|0)===0&&isFinite(S.u.b),'b='+S.u.b);const k=g.sb.STM.st();ok(isFinite(k.p)&&isFinite(k.f))});
t('tüzelés: a 🔥 több tüzet ad (korlát 1), üres tanknál nem',()=>{const{S,M}=kz();M.st();S.kz.f=.2;S.fuel=100;M.sc=0;M.stoke();ok(Math.abs(S.kz.f-.48)<1e-9,'f '+S.kz.f);S.fuel=0;M.sc=0;M.stoke();ok(Math.abs(S.kz.f-.48)<1e-9)});
t('kézi kazán: a nyomás a tűzzel nő, túlnyomásnál sérülés, majd repedés + szivárgás',()=>{const{S,M,st}=kz();M.st();S.kz.f=1;S.kz.p=.7;S.st='idle';S.hp=100;st(.1,200);ok(S.kz.p>1.1,'nyomás '+S.kz.p);st(.1,600);ok(S.hp<100||S.kz.lk,'sérülés/repedés hp='+S.hp)});
t('biztonsági szelepes kazán: magától enged, nem sérül, nem reped',()=>{const{S,M,st}=kz();S.u.b=1;M.st();S.kz.f=1;S.kz.p=.9;S.hp=100;st(.1,1500);ok(S.kz.p<1.2,'nyomás '+S.kz.p);eq(S.hp,100);eq(S.kz.lk,0)});
t('kézi szelep: nyomva tartva csökken a nyomás',()=>{const{S,M,st}=kz();M.st();S.kz.f=0;S.kz.p=1.1;M.held=1;st(.1,5);ok(S.kz.p<1.1-.3,'p '+S.kz.p)});
t('automata tüzelés: a tűz magától ~0,74-en áll, a 🔥 nem kell',()=>{const{S,M,st}=kz();S.u.b=3;M.st();S.kz.f=.05;st(.1,100);ok(Math.abs(S.kz.f-.74)<.02,'f '+S.kz.f)});
t('teljesítmény-szorzó: hideg kazánnal lassabb (.75), üzemi nyomásnál 1; a calc() használja',()=>{const{S,M,g}=kz();M.st();S.kz.p=0;ok(Math.abs(M.mult()-.75)<1e-9);S.kz.p=.9;eq(M.mult(),1);const c1=g.sb.calc().d[1];S.kz.p=0;const c0=g.sb.calc().d[1];ok(Math.abs(c0/c1-.75)<1e-6,'calc szorzó '+(c0/c1))});
t('helyszíni javítás: a szivárgás nyomva tartva a szint szerinti idő alatt elzárul; elengedve visszacsúszik',()=>{const{S,M,st}=kz();M.st();S.kz.lk=1;S.u.b=2;ok(M.need()===3);M.rh=1;st(.1,20);ok(S.kz.lk===1,'még szivárog');st(.1,15);eq(S.kz.lk,0);M.rh=0;S.kz.lk=1;M.rp=1;st(.1,10);ok(M.rp<.01)});
t('leesett lánc a mélyben megjavítható (1,6× idő), a szivárgás előbb',()=>{const{S,M,st,g}=kz();M.st();S.u.b=0;g.sb.DMG.st().t=1;ok(M.chain()&&Math.abs(M.need()-8)<1e-9);M.rh=1;st(.1,90);ok(!M.chain(),'lánc megjavítva')});
t('intelligens vezérlő: a szivárgást ~10 mp alatt magától lezárja',()=>{const{S,M,st}=kz();S.u.b=4;M.st();S.kz.lk=1;st(.1,120);eq(S.kz.lk,0)});
t('hosszú szünet utáni lépés (away): semmi sem romlik, biztonságos állapot',()=>{const{S,M}=kz();M.st();S.kz.p=1.4;S.kz.f=0;M.away();ok(S.kz.p<=.95&&S.kz.f>=.6)});
t('a kazán nem akasztja meg a játékot: fuzz-szerű kezelés után minden érték véges',()=>{const{S,M,st}=kz();M.st();for(let i=0;i<300;i++){M.held=Math.random()<.3?1:0;M.rh=Math.random()<.2?1:0;if(Math.random()<.2)M.sc=0,M.stoke();S.u.b=i%5;st(Math.random()*.3,3)}ok(isFinite(S.kz.p)&&isFinite(S.kz.f)&&S.kz.p>=0&&S.kz.f>=0&&S.kz.f<=1&&S.hp>=5)});

group('Z3) Íves forduló a föld alatt');
const arcG=(o)=>{const g=boot(),T=g.T,S=T.S;S.depth=60;S.x=0;S.tn=[[0,0,0,60]];S.tr=[['D',60]];S.st='idle';S.fuel=900;S.set.sc=60;S.cg={};S.en=1;if(o&&o.arc===0)S.set.arc=0;S.ahd='D';return g};
t('merőleges irányváltás föld alatt: ívben, kamra nélkül; a végén új irányban halad, a járat összefüggő',()=>{const g=arcG(),T=g.T,S=T.S,A=g.sb.ARC;T.go('D');g.frames(5,30);const ch0=S.ch?S.ch.length:0,d0=S.depth,x0=S.x;T.go('R');ok(!!A.pl,'terv van');ok(S.st==='D','az első szakasz a régi irány');const r=until(g,()=>!A.pl&&S.st==='R',6000);eq(r.errs,[]);ok(!A.pl&&S.st==='R','befejezte: '+S.st);ok(Math.abs((S.x-x0)-12)<.3,'dx '+(S.x-x0));ok(Math.abs((S.depth-d0)-12)<.3,'dy '+(S.depth-d0));eq(S.ch?S.ch.length:0,ch0,'nem fúrt kamrát');
 const tn=S.tn;for(let i=1;i<tn.length;i++){ok(Math.hypot(tn[i][0]-tn[i-1][2],tn[i][1]-tn[i-1][3])<2.3,'szakadás @'+i)}ok(tn.length>=8,'az ív több szakaszból áll: '+tn.length)});
t('az ív érintője: kanyar közben a gép szöge 0 és 90° között van, a végén visszaáll a régi tájolásra',()=>{const g=arcG(),T=g.T,A=g.sb.ARC;T.go('D');g.frames(5,30);T.go('R');let mid=null;for(let i=0;i<4000&&A.pl;i++){g.frames(1,30);if(A.pl&&A.pl.i===A.pl.legs.length>>1)mid=A.hd()}ok(mid&&mid.fc===1&&mid.ang>.3&&mid.ang<1.3,'középen '+JSON.stringify(mid));until(g,()=>!A.pl,6000);g.frames(400,30);eq(A.hd(),null)});
t('visszaút az íven át: a ⌂ gomb hazahozza a gépet, a verem következetes',()=>{const g=arcG(),T=g.T,S=T.S,A=g.sb.ARC;T.go('D');g.frames(5,30);T.go('R');until(g,()=>!A.pl&&S.st==='R',6000);g.frames(60,30);T.go('H');const r=until(g,()=>S.st==='idle'&&S.depth<1,40000);eq(r.errs,[]);ok(S.depth<1,'hazaért: '+S.depth.toFixed(1)+' '+S.st)});
t('megállítás az ív közben törli a tervet; ugyanarra az irányra újra nyomva az ív folytatódik',()=>{const g=arcG(),T=g.T,S=T.S,A=g.sb.ARC;T.go('D');g.frames(5,30);T.go('R');g.frames(40,30);ok(!!A.pl);T.go('idle');ok(!A.pl,'törölve');T.go('R');g.frames(20,30);ok(S.st==='R'||S.st==='D'||A.pl,'újra elindul: '+S.st);eq(g.sb.DBG&&g.sb.DBG.err||null,null)});
t('megfordulás (fel↔le, balra↔jobbra) és a kész járat előtti fordulás nem ívben történik',()=>{const g=arcG(),T=g.T,A=g.sb.ARC;T.go('D');g.frames(5,30);T.go('U');ok(!A.pl,'megfordulás: nincs ív');const g2=arcG(),T2=g2.T,S2=g2.T.S;S2.tn=[[0,0,0,60],[0,60,40,60]];S2.depth=60;T2.go('D');g2.frames(2,30);S2.depth=59.9;T2.go('R');ok(!g2.sb.ARC.pl,'kész járat előtt nincs ív')});
t('felszín közelében nincs ív (a régi viselkedés), és a beállítás kikapcsolja',()=>{const g=arcG(),T=g.T,S=T.S,A=g.sb.ARC;S.depth=10;T.go('D');g.frames(2,30);T.go('U');S.st='idle';S.depth=10;S.ahd='U';T.go('R');ok(!A.pl,'nincs hely felfelé íveléshez/felszín');const g2=arcG({arc:0}),A2=g2.sb.ARC;g2.T.go('D');g2.frames(5,30);g2.T.go('R');ok(!A2.pl,'ki van kapcsolva')});

group('Z4) Felszínről merülés ívben');
const dv=()=>{const g=boot(),T=g.T,S=T.S;g.engineOn();S.depth=0;S.x=-150;S.tr=[];S.fuel=900;S.cg={};S.set.sc=40;S.st='idle';return g};
t('a felszínről lefelé nyomva a gép ívben merül (nem áll függőlegesre), a végén lefelé fúr',()=>{const g=dv(),T=g.T,S=T.S,A=g.sb.ARC;T.go('R');g.frames(30,30);T.go('idle');g.frames(5,30);const x0=S.x;T.go('D');ok(!!A.pl,'ív-terv a felszínen');let mid=null,maxAng=0;for(let i=0;i<6000&&A.pl;i++){g.frames(1,30);const h=A.hd();if(h){maxAng=Math.max(maxAng,Math.abs(h.ang))}if(A.pl&&A.pl.i===A.pl.legs.length>>1)mid=h}ok(mid&&mid.ang>.3&&mid.ang<1.3,'középen ferde: '+JSON.stringify(mid));ok(!A.pl&&S.st==='D','befejezte, lefelé fúr: '+S.st);ok(S.x-x0>11,'előrehaladt: '+(S.x-x0).toFixed(1));ok(S.depth>10,'lement: '+S.depth.toFixed(1))});
t('a merülés közben a gép sosem áll 90°-nál nagyobb szögben a kezdéskor (a hátulja nem emelkedik): az első lépéseknél a szög kicsi',()=>{const g=dv(),T=g.T,S=T.S,A=g.sb.ARC;T.go('R');g.frames(20,30);T.go('idle');T.go('D');let first=null;for(let i=0;i<4000&&!first;i++){g.frames(1,30);if(A.pl&&A.pl.i>=4){const h=A.hd();first=h?h.ang:0}}ok(first!==null&&first<.4,'4 szakasz után még lapos: '+first)});
t('kikapcsolt beállításnál a régi viselkedés (nincs ív-terv)',()=>{const g=dv(),T=g.T,S=T.S;S.set.arc=0;T.go('R');g.frames(20,30);T.go('idle');T.go('D');ok(!g.sb.ARC.pl)});
t('merülés felszíni járatnál (kész járat a gép előtt) és felfelé nem ível',()=>{const g=dv(),T=g.T,S=T.S;T.go('R');g.frames(20,30);T.go('idle');T.go('U');ok(!g.sb.ARC.pl,'felfelé a felszínről nincs ív')});

t('simaság: a merülés közben a haladás és a mód nem váltogat szakaszonként (nincs villogás/ugrás)',()=>{const g=boot(),T=g.T,S=T.S;g.engineOn();S.depth=0;S.x=-150;S.tr=[];S.fuel=900;S.cg={};S.set.sc=40;S.st='idle';T.go('R');g.frames(30,30);T.go('idle');T.go('D');const A=g.sb.ARC,modes=new Set();let maxJump=0,px=S.x,pd=S.depth;for(let i=0;i<3000&&A.pl;i++){g.frames(1,30);modes.add(S.mode);maxJump=Math.max(maxJump,Math.hypot(S.x-px,S.depth-pd));px=S.x;pd=S.depth}eq([...modes],['drill']);ok(maxJump<1.5,'legnagyobb ugrás képkockánként: '+maxJump.toFixed(2))});

group('Z5) Gyors megfordulás (nincs pörgés, nincs forgókamra-kényszer)');
const sn=()=>{const g=boot(),T=g.T,S=T.S;g.engineOn();S.depth=80;S.x=0;S.tn=[[0,0,0,80]];S.tr=[['D',80]];S.fuel=900;S.cg={};S.set.sc=30;S.set.arc=1;return g};
t('megfordulás föld alatt (jobbra→balra): a modell ≤0,3 mp alatt átfordul, kamra nélkül, és azonnal halad',()=>{const g=sn(),T=g.T,S=T.S,C=g.sb.CH;T.go('R');g.frames(60,30);const n0=C?C.list().length:0,x0=S.x;T.go('L');let f=0;const vm=require('vm');for(;f<40;f++){g.frames(1,16);const y=vm.runInContext('Math.abs(yaw-Math.PI)',g.sb);if(y<.05)break}ok(f*16<=300,'átfordulás '+f*16+' ms');g.frames(60,30);ok(S.x<x0-.01,'balra halad: '+(S.x-x0).toFixed(2));eq(C?C.list().length:0,n0)});
t('megfordulás fel↔le a járatban: azonnal visszafordul és halad, nem áll meg forgókamráért',()=>{const g=sn(),T=g.T,S=T.S;T.go('D');g.frames(60,30);const d0=S.depth;T.go('U');g.frames(80,30);ok(S.depth<d0-.01,'fölfelé: '+(S.depth-d0).toFixed(2))});
t('a beállítással kikapcsolva a régi (lassú, kamrás) megfordulás marad',()=>{const g=sn(),T=g.T,S=T.S,C=g.sb.CH;S.set.snap=0;T.go('R');g.frames(40,30);const n0=C.list().length;T.go('L');g.frames(10,30);ok(C.act===1,'ásás indul')});

console.log(`\nÖsszesen: ${pass} sikeres, ${fail} sikertelen`);process.exit(fail?1:0);
